/* Test savollari tushuntirishlarining tarjimasi: id → [ruscha, inglizcha] */
window.PW_QTR = {
  e001: ["<b>안전모</b> (anjeonmo) — защитная каска. Её надевают для защиты головы; с головными уборами используется глагол 쓰다. 장갑 — перчатки, 앞치마 — фартук, 마스크 — маска.", "<b>안전모</b> (anjeonmo) — a safety helmet. It protects your head; headwear takes the verb 쓰다. 장갑 — gloves, 앞치마 — apron, 마스크 — mask."],
  e002: ["<b>출근하다</b> — приходить на работу. Речь о том, чтобы приходить на работу «каждое утро в 8». 퇴근하다 — уходить с работы, 결근하다 — не выйти на работу, 졸업하다 — окончить учёбу.", "<b>출근하다</b> — to go to work. The sentence is about arriving at work \"every morning at 8\". 퇴근하다 — to leave work, 결근하다 — to miss work, 졸업하다 — to graduate."],
  e003: ["<b>금연</b> (geumyeon) — курить запрещено. 금 = запрет, 연 = дым. -(으)면 안 됩니다 — форма запрета «нельзя …».", "<b>금연</b> (geumyeon) — no smoking. 금 = ban, 연 = smoke. -(으)면 안 됩니다 is the \"you must not …\" form."],
  e004: ["<b>반장</b> — бригадир. Вопрос: «Куда поставить эту коробку?» Ответ должен назвать место: 창고에 놓으세요 — «Поставьте на склад». 창고 — склад.", "<b>반장</b> — team leader. Question: \"Where should I put this box?\" The answer must name a place: 창고에 놓으세요 — \"Put it in the warehouse\". 창고 — warehouse."],
  e005: ["«Сегодня много работы, поэтому нужно поработать на два часа дольше». Это <b>잔업</b> (сверхурочная работа). 월급 — зарплата, 휴가 — отпуск, 기숙사 — общежитие.", "\"There's a lot of work today, so we need to work two extra hours.\" That's <b>잔업</b> (overtime). 월급 — salary, 휴가 — holiday, 기숙사 — dormitory."],
  e006: ["«Если поранились во время работы, сразу сообщите руководителю». 다치다 — пораниться, <b>바로</b> — сразу, 관리자 — руководитель, менеджер.", "\"If you get hurt at work, tell your manager right away.\" 다치다 — to get hurt, <b>바로</b> — right away, 관리자 — manager."],
  e007: ["월급날 — день зарплаты, 매달 — каждый месяц, 통장 — банковский счёт. В тексте сказано: «<b>25-го числа каждого месяца</b>».", "월급날 — payday, 매달 — every month, 통장 — bank account. The text says \"<b>the 25th of every month</b>\"."],
  e008: ["<b>-기 전에</b> — «перед тем как»: «Перед чисткой станка нужно выключить ток». 후에 используется в форме -(으)ㄴ 후에 (청소한 후에), а не с -기.", "<b>-기 전에</b> — \"before …\": \"Turn off the power before cleaning the machine.\" 후에 comes as -(으)ㄴ 후에 (청소한 후에), not with -기."],
  e009: ["<b>장갑</b> (janggap) — перчатки. 모자 — шапка, 신발 — обувь, 양말 — носки.", "<b>장갑</b> (janggap) — gloves. 모자 — hat, 신발 — shoes, 양말 — socks."],
  e010: ["<b>소화기</b> (sohwagi) — огнетушитель. Все слова оканчиваются на <b>-기</b> (прибор): 전화기 — телефон, 세탁기 — стиральная машина, 청소기 — пылесос.", "<b>소화기</b> (sohwagi) — fire extinguisher. They all end in <b>-기</b> (device): 전화기 — telephone, 세탁기 — washing machine, 청소기 — vacuum cleaner."],
  e011: ["<b>출입 금지</b> — вход запрещён. 출입 = вход и выход, 금지 = запрет. Стоит у опасных участков на заводе.", "<b>출입 금지</b> — no entry. 출입 = going in and out, 금지 = ban. You see it at dangerous areas in factories."],
  e012: ["<b>비상구</b> (bisanggu) — аварийный выход. 비상 = чрезвычайная ситуация, 구 = выход. Через него выходят при пожаре и другой опасности.", "<b>비상구</b> (bisanggu) — emergency exit. 비상 = emergency, 구 = opening/exit. Used in a fire or other danger."],
  e013: ["В корейском «надевать» зависит от вещи: одежда — <b>입다</b>, обувь — 신다, головной убор/очки — 쓰다, перчатки/кольцо — 끼다. Очень часто встречается в EPS!", "In Korean, \"to wear\" depends on the item: clothes — <b>입다</b>, shoes — 신다, hats/glasses — 쓰다, gloves/rings — 끼다. Very common in EPS!"],
  e014: ["С перчатками (장갑) используется <b>끼다</b>. <b>-지 않도록</b> — «чтобы не…»: наденьте перчатки, чтобы не поранить руки.", "Gloves (장갑) take <b>끼다</b>. <b>-지 않도록</b> — \"so as not to …\": wear gloves so you don't hurt your hands."],
  e015: ["<b>내일</b> (завтра) — нужно будущее время: <b>-(으)ㄹ 거예요</b>. 쉬다 → 쉴 거예요 (отдохну). Остальные варианты — прошедшее время.", "<b>내일</b> (tomorrow) needs the future: <b>-(으)ㄹ 거예요</b>. 쉬다 → 쉴 거예요 (I'll rest). The others are past tense."],
  e016: ["Вопрос: «Что у вас болит?» — спрашивают <b>어디</b> (где), поэтому отвечают частью тела: <b>머리가 아파요</b> — болит голова.", "The question \"Where does it hurt?\" asks <b>어디</b> (where), so answer with a body part: <b>머리가 아파요</b> — my head hurts."],
  e017: ["<b>언제까지</b> — «до какого времени». В ответе нужно время: <b>오후 5시까지요</b> — до пяти вечера.", "<b>언제까지</b> — \"by when\". The answer needs a time: <b>오후 5시까지요</b> — by 5 pm."],
  e018: ["<b>공지</b> — объявление, <b>점검</b> — техосмотр. Утром работы нет, нужно прийти <b>до 13:00</b> (오후 1시까지).", "<b>공지</b> — notice, <b>점검</b> — inspection. No work in the morning; come in <b>by 1 pm</b> (오후 1시까지)."],
  e019: ["«На выходных хожу на курсы корейского» = <b>주말에 한국어를 배웁니다</b>. 부품 — запчасть, 학원 — курсы.", "\"I go to a Korean course at weekends\" = <b>주말에 한국어를 배웁니다</b>. 부품 — parts, 학원 — private academy/course."],
  e020: ["<b>-(으)ㄴ 후에</b> — «после»: принимайте после еды. 전에 используется как -기 전에 (먹기 전에), а не с 먹은.", "<b>-(으)ㄴ 후에</b> — \"after\": take it after meals. 전에 goes as -기 전에 (먹기 전에), not with 먹은."],
  e021: ["<b>미끄럼 주의</b> — «Скользко, осторожно». <b>주의</b> — внимание. Похожие: 화재 주의 (осторожно, пожар), 감전 주의 (осторожно, током).", "<b>미끄럼 주의</b> — \"Slippery, caution\". <b>주의</b> — caution. Similar: 화재 주의 (fire hazard), 감전 주의 (risk of electric shock)."],
  e022: ["<b>월급</b> — месячная зарплата. 용돈 — карманные деньги, 세금 — налог, 요금 — плата (за свет, телефон).", "<b>월급</b> — monthly salary. 용돈 — pocket money, 세금 — tax, 요금 — fee (electricity, phone)."],
  e023: ["<b>기숙사</b> — общежитие, <b>규칙</b> — правило. Правило 2: <b>방에서 요리하면 안 됩니다</b> — в комнате готовить нельзя.", "<b>기숙사</b> — dormitory, <b>규칙</b> — rule. Rule 2: <b>방에서 요리하면 안 됩니다</b> — no cooking in the room."],
  e024: ["<b>바로</b> — сразу. «Если станок сломался, сразу скажите бригадиру». 천천히 — медленно, 가끔 — иногда, 아직 — ещё. <b>고장 나다</b> — сломаться.", "<b>바로</b> — right away. \"If the machine breaks, tell the team leader right away.\" 천천히 — slowly, 가끔 — sometimes, 아직 — still/yet. <b>고장 나다</b> — to break down."],
  e025: ["«Место, где производят вещи, много станков» — <b>공장</b> (завод, фабрика).", "\"A place where things are made, with lots of machines\" — <b>공장</b> (factory)."],
  e026: ["<b>버스</b> — автобус. 택시 — такси, 지하철 — метро, 자전거 — велосипед.", "<b>버스</b> — bus. 택시 — taxi, 지하철 — subway, 자전거 — bicycle."],
  e027: ["<b>망치</b> (mangchi) — молоток. ✂️ 가위 — ножницы, 🔑 열쇠 — ключ, 🧹 빗자루 — веник.", "<b>망치</b> (mangchi) — hammer. ✂️ 가위 — scissors, 🔑 열쇠 — key, 🧹 빗자루 — broom."],
  e028: ["<b>가위</b> (gawi) — ножницы.", "<b>가위</b> (gawi) — scissors."],
  e029: ["<b>사과 세 개</b> — три яблока. При счёте предметов — корейские числа: 하나, 둘, <b>셋 → 세 개</b>. 배 🍐 — груша, 바나나 🍌 — банан.", "<b>사과 세 개</b> — three apples. Counting uses native numbers: 하나, 둘, <b>셋 → 세 개</b>. 배 🍐 — pear, 바나나 🍌 — banana."],
  e030: ["<b>엘리베이터 옆</b> — рядом с лифтом. <b>옆</b> — рядом, 안 — внутри, 밖 — снаружи. <b>실례합니다</b> — извините (при обращении).", "<b>엘리베이터 옆</b> — next to the elevator. <b>옆</b> — next to, 안 — inside, 밖 — outside. <b>실례합니다</b> — excuse me (to get attention)."],
  e031: ["<b>몇 시에</b> — во сколько? <b>퇴근하다</b> — уходить с работы. В ответе нужно время: 6시에 퇴근해요.", "<b>몇 시에</b> — at what time? <b>퇴근하다</b> — to leave work. The answer needs a time: 6시에 퇴근해요."],
  e032: ["<b>고향</b> — родной город, родина. На вопрос «Откуда вы?» отвечают названием места.", "<b>고향</b> — hometown. Answer \"Where are you from?\" with a place name."],
  e033: ["<b>-(으)ㄹ 수 있어요?</b> — «Вы можете…?» <b>혼자</b> — один, самостоятельно. Ответ в той же форме: 네, 혼자 할 수 있어요.", "<b>-(으)ㄹ 수 있어요?</b> — \"Can you …?\" <b>혼자</b> — alone, by yourself. Answer in the same form: 네, 혼자 할 수 있어요."],
  e034: ["«Каждый месяц отправляю половину зарплаты семье на родину» — это <b>송금</b> (денежный перевод). <b>반</b> — половина.", "\"Every month I send half my salary to my family back home\" — that's <b>송금</b> (remittance). <b>반</b> — half."],
  e035: ["«Что у вас болит? — Со вчерашнего дня температура и кашель» — <b>병원</b> (больница). <b>열이 나다</b> — температурить, <b>기침</b> — кашель.", "\"Where does it hurt? — I've had a fever and a cough since yesterday\" — <b>병원</b> (hospital/clinic). <b>열이 나다</b> — to have a fever, <b>기침</b> — cough."],
  e036: ["<b>소포</b> — посылка, <b>저울</b> — весы. Посылки отправляют на <b>우체국</b> (почта).", "<b>소포</b> — parcel, <b>저울</b> — scales. Parcels are sent from the <b>우체국</b> (post office)."],
  e037: ["«Завтра сильный дождь, возьмите зонт». <b>우산</b> — зонт, <b>맑다</b> — ясно (о погоде).", "\"It'll rain a lot tomorrow, bring an umbrella.\" <b>우산</b> — umbrella, <b>맑다</b> — clear (weather)."],
  e038: ["<b>반드시 = 꼭</b> — обязательно. <b>안전화</b> — защитная обувь, <b>작업장</b> — рабочий участок (цех).", "<b>반드시 = 꼭</b> — must, definitely. <b>안전화</b> — safety shoes, <b>작업장</b> — work area (shop floor)."],
  e039: ["<b>-아/어도 될까요?</b> — «можно…?» (просьба о разрешении). Причина: <b>병원에 가야 해서</b> — нужно в больницу. <b>몸조심하세요</b> — берегите себя.", "<b>-아/어도 될까요?</b> — \"may I …?\" (asking permission). Reason: <b>병원에 가야 해서</b> — he has to go to hospital. <b>몸조심하세요</b> — take care of yourself."],
  e040: ["<b>옮기다</b> — переносить. «Отнесите эти коробки на склад. — Сейчас же отнесу».", "<b>옮기다</b> — to move, carry. \"Please take these boxes to the warehouse. — I'll do it right now.\""],
  e041: ["<b>비가 와요</b> — идёт дождь. 눈이 와요 ❄️ — идёт снег, 맑아요 ☀️ — ясно, 바람이 불어요 💨 — дует ветер.", "<b>비가 와요</b> — it's raining. 눈이 와요 ❄️ — it's snowing, 맑아요 ☀️ — it's clear, 바람이 불어요 💨 — it's windy."],
  e042: ["<b>눈</b> — снег (глаз тоже 눈!). <b>눈이 와요</b> — идёт снег.", "<b>눈</b> — snow (it also means \"eye\"!). <b>눈이 와요</b> — it's snowing."],
  e043: ["«Что вы обычно делаете на выходных?» — с <b>보통</b> (обычно) отвечают в настоящем времени: 친구들하고 축구를 해요.", "\"What do you usually do at weekends?\" — <b>보통</b> (usually) takes the present tense: 친구들하고 축구를 해요."],
  e044: ["<b>-부터 -까지</b> — «с … до …». С 12 до 1 = один час. Столовая на <b>1층</b> (1-м этаже).", "<b>-부터 -까지</b> — \"from … to …\". 12 to 1 = one hour. The canteen is on <b>1층</b> (the 1st floor)."],
  e045: ["Про защитные очки и перчатки — это <b>안전</b> (безопасность). С очками — <b>쓰다</b>, с перчатками — <b>끼다</b>.", "Safety glasses and gloves — this is about <b>안전</b> (safety). Glasses take <b>쓰다</b>, gloves take <b>끼다</b>."],
  e046: ["<b>운동화</b> — кроссовки. <b>오만 원</b> — 50 000 вон. <b>싸게 해 주세요</b> — сделайте подешевле (торг).", "<b>운동화</b> — sneakers. <b>오만 원</b> — 50,000 won. <b>싸게 해 주세요</b> — make it cheaper, please (bargaining)."],
  e047: ["<b>스패너</b> — гаечный ключ. 드라이버 — отвёртка, 망치 — молоток, 톱 — пила.", "<b>스패너</b> — spanner, wrench. 드라이버 — screwdriver, 망치 — hammer, 톱 — saw."],
  e048: ["<b>손 조심</b> — «Берегите руки»: руку может зажать станком. 조심 — осторожность.", "<b>손 조심</b> — \"Watch your hands\": the machine can trap them. 조심 — caution."],
  e049: ["После работы <b>выключите</b> станок — <b>끄다</b>. 켜다 — включать, 타다 — ехать, 열다 — открывать.", "<b>Turn off</b> the machine after work — <b>끄다</b>. 켜다 — turn on, 타다 — ride, 열다 — open."],
  e050: ["<b>-(으)ㄴ 지 + время + 되다</b> — «прошло … с тех пор как»: я в Корее уже год.", "<b>-(으)ㄴ 지 + time + 되다</b> — \"it has been … since\": it's been a year since I came to Korea."],
  e051: ["«Эта коробка очень тяжёлая» — ответ: <b>제가 도와드릴게요</b> (я помогу). 무겁다 — тяжёлый, 가볍다 — лёгкий.", "\"This box is too heavy\" — the fitting reply: <b>제가 도와드릴게요</b> (I'll help you). 무겁다 — heavy, 가볍다 — light."],
  e052: ["<b>창립 기념일</b> — день основания компании. «Все сотрудники отдыхают» — <b>쉽니다</b>. 평소처럼 — как обычно.", "<b>창립 기념일</b> — the company's founding day. \"All staff have the day off\" — <b>쉽니다</b>. 평소처럼 — as usual."],
  e053: ["<b>병가</b> — больничный. 휴일 — выходной, 출장 — командировка, 퇴근 — уход с работы.", "<b>병가</b> — sick leave. 휴일 — day off, 출장 — business trip, 퇴근 — leaving work."],
  e054: ["Запрет: <b>-지 마세요</b> — «не …». Опасно, не заходите за линию: 들어가<b>지 마세요</b>.", "Prohibition: <b>-지 마세요</b> — \"don't …\". It's dangerous, don't go inside this line: 들어가<b>지 마세요</b>."],
  e055: ["«Получив зарплату, сначала отправляю деньги домой, остальное кладу в банк». <b>저금하다</b> — копить, 남다 — оставаться.", "\"When I get paid, I first send money home and save the rest in the bank.\" <b>저금하다</b> — to save money, 남다 — to remain."],
  e056: ["<b>구급차</b> — скорая помощь (номер 119). 소방차 — пожарная машина, 경찰차 — полицейская машина.", "<b>구급차</b> — ambulance (call 119). 소방차 — fire engine, 경찰차 — police car."],
  e057: ["<b>열쇠</b> (yeolsoe) — ключ. ✂️ 가위 — ножницы, 🔨 망치 — молоток, 📏 자 — линейка.", "<b>열쇠</b> (yeolsoe) — key. ✂️ 가위 — scissors, 🔨 망치 — hammer, 📏 자 — ruler."],
  e058: ["<b>자</b> (ja) — линейка. Нужна, чтобы измерять длину.", "<b>자</b> (ja) — ruler, used to measure length at work."],
  e059: ["<b>어디에서</b> — где? В ответе нужно место: 자동차 부품 공장 — завод автозапчастей.", "<b>어디에서</b> — where? The answer needs a place: 자동차 부품 공장 — car parts factory."],
  e060: ["<b>어떻게</b> — как? Ответ объясняет способ: «Нажмите эту кнопку — и включится». 누르다 — нажимать.", "<b>어떻게</b> — how? The answer explains the method: \"Press this button and it turns on.\" 누르다 — to press."],
  e061: ["Стрижка — <b>미용실</b> (парикмахерская). 세탁소 — химчистка, 약국 — аптека.", "A haircut — <b>미용실</b> (hair salon). 세탁소 — dry cleaner's, 약국 — pharmacy."],
  e062: ["Постирать рубашку — <b>세탁소</b> (химчистка, прачечная). 빨다 — стирать, 찾다 — забрать.", "Washing a shirt — <b>세탁소</b> (laundry, dry cleaner's). 빨다 — to wash, 찾다 — to pick up."],
  e063: ["<b>공구</b> — инструменты, <b>제자리</b> — своё место, <b>정리하다</b> — убирать. После работы инструменты кладут на место.", "<b>공구</b> — tools, <b>제자리</b> — their proper place, <b>정리하다</b> — to tidy up. Put the tools back after work."],
  e064: ["<b>놓치다</b> — упустить: опоздал, потому что пропустил автобус. 늦잠을 자다 — проспать.", "<b>놓치다</b> — to miss: he was late because he missed the bus. 늦잠을 자다 — to oversleep."],
  e065: ["«Со следующего месяца зарплата вырастет на 100 000 вон» — речь о <b>월급</b>. 오르다 — повышаться.", "\"From next month the salary goes up by 100,000 won\" — it's about <b>월급</b>. 오르다 — to rise."],
  e066: ["«Как жизнь в Корее?» — спрашивают мнение: «Сначала было трудно, а сейчас нормально». <b>-지만</b> — но.", "\"How's life in Korea?\" — asks for an opinion: \"It was hard at first, but now it's fine.\" <b>-지만</b> — but."],
  e067: ["<b>사다리</b> — лестница-стремянка, для работы на высоте. 의자 — стул, 책상 — стол, 상자 — коробка.", "<b>사다리</b> — ladder, used for work at height. 의자 — chair, 책상 — desk, 상자 — box."],
  e068: ["<b>빗자루</b> — веник, метла. 걸레 — тряпка, 쓰레기통 — мусорное ведро, 청소기 — пылесос.", "<b>빗자루</b> — broom. 걸레 — mop cloth, 쓰레기통 — trash can, 청소기 — vacuum cleaner."],
  e069: ["<b>안전 조끼</b> — сигнальный жилет. 안전모 — каска, 안전화 — защитная обувь.", "<b>안전 조끼</b> — safety vest. 안전모 — hard hat, 안전화 — safety shoes."],
  e070: ["<b>화기 엄금</b> — открытый огонь строго запрещён. 화기 — огонь, 엄금 — строгий запрет. Висит там, где хранятся горючие вещества.", "<b>화기 엄금</b> — open flames strictly prohibited. 화기 — fire, 엄금 — strict ban. Posted where flammable materials are stored."],
  e071: ["<b>머리 조심</b> — «Берегите голову»: низкий потолок. <b>부딪치다</b> — удариться. 머리를 감다 — мыть голову.", "<b>머리 조심</b> — \"Mind your head\": low ceiling. <b>부딪치다</b> — to bump. 머리를 감다 — to wash your hair."],
  e072: ["<b>보호구 착용</b> — наденьте средства защиты. 보호구 — защитное снаряжение (каска, перчатки, очки), <b>착용</b> — ношение.", "<b>보호구 착용</b> — wear protective gear. 보호구 — protective equipment (helmet, gloves, goggles), <b>착용</b> — wearing."],
  e073: ["Желание: <b>-고 싶다</b> — «хочу …». 잘하고 싶어요 — хочу хорошо владеть.", "Wish: <b>-고 싶다</b> — \"want to …\". 잘하고 싶어요 — I want to be good at it."],
  e074: ["<b>-기 전에</b> — «перед тем как». Перед работой на станке нужно пройти инструктаж по безопасности.", "<b>-기 전에</b> — \"before …ing\". Before using the machine you must take safety training."],
  e075: ["<b>-(으)ㄴ 후에</b> — «после того как». Принимайте лекарство после еды. 드세요 — от 드시다 (вежливо «есть, пить»).", "<b>-(으)ㄴ 후에</b> — \"after …ing\". Take this medicine after eating. 드세요 — from 드시다 (honorific eat/drink)."],
  e076: ["Обязанность: <b>-아/어야 하다</b> — «нужно, должен». 끝내야 해요 — нужно закончить.", "Obligation: <b>-아/어야 하다</b> — \"must, have to\". 끝내야 해요 — it has to be finished."],
  e077: ["<b>-(으)ㄹ 수 있다</b> — «могу …». Основа 만들다 кончается на ㄹ, поэтому <b>만들 수 있어요</b>.", "<b>-(으)ㄹ 수 있다</b> — \"can …\". The stem 만들다 ends in ㄹ, so it is <b>만들 수 있어요</b>."],
  e078: ["<b>-거나</b> — «или». По выходным убираюсь или стираю. -지만 — но, -니까 — потому что.", "<b>-거나</b> — \"or\". On weekends I clean or do laundry. -지만 — but, -니까 — because."],
  e079: ["Цель: <b>-(으)려고</b> — «чтобы». Пошёл в банк, чтобы снять деньги. 돈을 찾다 — снимать деньги.", "Purpose: <b>-(으)려고</b> — \"in order to\". I went to the bank to withdraw money. 돈을 찾다 — to withdraw money."],
  e080: ["Просьба о разрешении: <b>-아/어도 돼요?</b> — «можно …?». Ответ в той же форме: 네, 쉬어도 돼요. 반장 — бригадир.", "Asking permission: <b>-아/어도 돼요?</b> — \"may I …?\". The answer uses the same form: 네, 쉬어도 돼요. 반장 — team leader."],
  e081: ["<b>-아/어 보다</b> — «попробовать». «Можно примерить?» — «Да, примерьте вон там».", "<b>-아/어 보다</b> — \"try …ing\". \"May I try this on?\" — \"Yes, try it on over there.\""],
  e082: ["Счётные слова: люди — <b>명</b>, предметы — 개, листы — 장, машины и техника — 대.", "Counters: people — <b>명</b>, things — 개, sheets — 장, vehicles and machines — 대."],
  e083: ["Листы бумаги считают словом <b>장</b>: 세 장 — три листа. 병 — бутылка, 대 — машина.", "Sheets of paper take the counter <b>장</b>: 세 장 — three sheets. 병 — bottle, 대 — vehicle."],
  e084: ["<b>점심시간</b> — обеденный перерыв: с 12 до 13, то есть <b>1시간</b>. 근무 — работа.", "<b>점심시간</b> — lunch break: from 12 to 1, so <b>1시간</b> (one hour). 근무 — work shift."],
  e085: ["<b>기숙사</b> — общежитие. Оно рядом с заводом, 5 минут пешком: значит, можно дойти пешком. Комната маленькая, но чистая.", "<b>기숙사</b> — dormitory. It's next to the factory, 5 minutes on foot, so you can walk there. The room is small but clean."],
  e086: ["Место, где покупают лекарства, — <b>약국</b> (аптека). 우체국 — почта, 은행 — банк, 시장 — рынок.", "The place to buy medicine is <b>약국</b> (pharmacy). 우체국 — post office, 은행 — bank, 시장 — market."],
  e087: ["Место, где отправляют письма и посылки, — <b>우체국</b> (почта). 소포 — посылка, 편지 — письмо.", "The place to send letters or parcels is <b>우체국</b> (post office). 소포 — parcel, 편지 — letter."],
  e088: ["Главная мысль — в первом предложении: время прихода на работу нужно соблюдать. <b>지키다</b> — соблюдать.", "The main idea is in the first sentence: you must be on time for work. <b>지키다</b> — to keep, to observe."],
  e089: ["О старших — уважительная форма: 자다 → <b>주무시다</b> (спать). <b>께서</b> — вежливая форма 이/가.", "Honorific for elders: 자다 → <b>주무시다</b> (to sleep). <b>께서</b> is the honorific form of 이/가."],
  e090: ["<b>사다리</b> (sadari) — лестница. 🔨 망치 — молоток, 🧯 소화기 — огнетушитель, 🧤 장갑 — перчатки.", "<b>사다리</b> (sadari) — ladder. 🔨 망치 — hammer, 🧯 소화기 — fire extinguisher, 🧤 장갑 — gloves."],
  e091: ["<b>소화기</b> (sohwagi) — огнетушитель. Первое, что нужно при пожаре.", "<b>소화기</b> (sohwagi) — fire extinguisher, the first thing you need in a fire."],
  e092: ["<b>빗자루</b> (bitjaru) — веник. 🪣 양동이 — ведро, 📏 자 — линейка.", "<b>빗자루</b> (bitjaru) — broom. 🪣 양동이 — bucket, 📏 자 — ruler."],
  e093: ["<b>어디에서</b> — где? В ответе нужно место: 회사 식당 — столовая компании. 보통 — обычно.", "<b>어디에서</b> — where? The answer needs a place: 회사 식당 — the company cafeteria. 보통 — usually."],
  e094: ["<b>-(으)ㄴ 지 얼마나 됐어요?</b> — «сколько прошло с тех пор как…?». В ответе срок: 2년쯤 — около двух лет.", "<b>-(으)ㄴ 지 얼마나 됐어요?</b> — \"how long has it been since…?\". The answer is a period: 2년쯤 — about two years."],
  e095: ["<b>몇 명</b> — сколько человек? Людей считают корейскими числами: 다섯 명 — пять человек.", "<b>몇 명</b> — how many people? People are counted with native Korean numbers: 다섯 명 — five people."],
  e096: ["Вопрос в прошедшем времени (<b>했어요</b>), ответ тоже. 등산 — поход в горы.", "The question is in the past tense (<b>했어요</b>), so is the answer. 등산 — hiking."],
  e097: ["«Куда едем? — До Сеульского вокзала, пожалуйста» — это <b>택시</b>. 역 — станция, вокзал.", "\"Where to? — Seoul Station, please.\" — it's a <b>택시</b> (taxi). 역 — station."],
  e098: ["«Что болит? — Со вчера температура и болит голова» — <b>병원</b> (больница). 열이 나다 — температурить.", "\"Where does it hurt? — I've had a fever and a headache since yesterday.\" — <b>병원</b> (hospital). 열이 나다 — to have a fever."],
  e099: ["Перевод денег домой, номер счёта — <b>은행</b> (банк). <b>계좌 번호</b> — номер счёта, 송금 — перевод.", "Sending money home and an account number — <b>은행</b> (bank). <b>계좌 번호</b> — account number, 송금 — remittance."],
  e100: ["<b>잔업</b> — сверхурочная работа. Мужчина должен работать до 8 вечера, то есть сегодня у него сверхурочные.", "<b>잔업</b> — overtime. The man has to work until 8 p.m., so he's doing overtime today."],
  e101: ["«Без каски в цех входить нельзя» — значит, входить только в каске. <b>작업장</b> — рабочая зона, цех.", "\"Without a hard hat you cannot enter the work area\" — so you must wear one. <b>작업장</b> — work area, workshop."],
  e102: ["<b>이상한 소리가 나다</b> — издавать странный звук. Мужчина сказал «Сначала выключу станок»: <b>끄다</b> — выключать. Правило безопасности: при неполадке сначала остановите станок.", "<b>이상한 소리가 나다</b> — to make a strange noise. The man said \"I'll turn the machine off first\": <b>끄다</b> — to turn off. Safety rule: if something is wrong, stop the machine first."],
  e103: ["Распорядок дня: подъём, зарядка, завтрак, работа. Это <b>하루 생활</b> — распорядок дня.", "A daily routine: getting up, exercise, breakfast, work. That's <b>하루 생활</b> — daily life."],
  e104: ["Дождь, ветер, зонт — речь о <b>날씨</b> (погоде). <b>-겠-</b> — предположение: «будет».", "Rain, wind, umbrella — it's about <b>날씨</b> (weather). <b>-겠-</b> expresses a forecast: \"will\"."],
  e105: ["<b>처음 뵙겠습니다</b> — «Рад познакомиться» (первая встреча). Ответ: <b>반갑습니다</b> и представиться.", "<b>처음 뵙겠습니다</b> — \"Nice to meet you\" (first meeting). Reply with <b>반갑습니다</b> and introduce yourself."],
  e106: ["Ответ на благодарность: <b>아니에요</b> / <b>별말씀을요</b> — «Не за что». 축하합니다 — поздравляю.", "Replying to thanks: <b>아니에요</b> / <b>별말씀을요</b> — \"Don't mention it\". 축하합니다 — congratulations."],
  e107: ["<b>소</b> — корова. В животноводстве: 돼지 — свинья, 닭 — курица, 말 — лошадь.", "<b>소</b> — cow. In livestock farming: 돼지 — pig, 닭 — chicken, 말 — horse."],
  e108: ["<b>트랙터</b> — трактор (сельское хозяйство). 트럭 — грузовик, 지게차 — погрузчик, 기차 — поезд.", "<b>트랙터</b> — tractor (farming). 트럭 — truck, 지게차 — forklift, 기차 — train."],
  e109: ["<b>반창고</b> — пластырь. 붕대 — бинт, 연고 — мазь, 체온계 — градусник.", "<b>반창고</b> — adhesive bandage. 붕대 — gauze bandage, 연고 — ointment, 체온계 — thermometer."],
  e110: ["<b>추락 주의</b> — «Осторожно, опасность падения». 추락 — падение с высоты, 떨어지다 — упасть.", "<b>추락 주의</b> — \"Caution: fall hazard\". 추락 — fall from height, 떨어지다 — to fall."],
  e111: ["<b>감전 주의</b> — «Осторожно, удар током». 감전 — удар током, 만지다 — трогать. 아껴 쓰다 — экономить.", "<b>감전 주의</b> — \"Danger: electric shock\". 감전 — electric shock, 만지다 — to touch. 아껴 쓰다 — to use sparingly."],
  e112: ["Сравнение: <b>N보다 더</b> — «более, чем N». 제일/가장 — самый, с 보다 не употребляются.", "Comparison: <b>N보다 더</b> — \"more than N\". 제일/가장 mean \"most\" and don't go with 보다."],
  e113: ["<b>-(으)ㄹ 때</b> — «когда». 일을 할 때 — во время работы. Не пользуйтесь телефоном на работе.", "<b>-(으)ㄹ 때</b> — \"when\". 일을 할 때 — while working. Don't use your phone while working."],
  e114: ["<b>-(으)면서</b> — «одновременно». Занимаюсь спортом, слушая музыку.", "<b>-(으)면서</b> — \"while\" (two actions at once). I exercise while listening to music."],
  e115: ["Причина: <b>-기 때문에</b> — «из-за того, что». Из-за сильного дождя сегодня на улице не работаем.", "Reason: <b>-기 때문에</b> — \"because\". Because it's raining hard, we won't work outside today."],
  e116: ["Просьба: <b>-아/어 주세요</b> — «сделайте, пожалуйста». 전하다 → 전해 주세요 — передайте. 서류 — документы.", "Request: <b>-아/어 주세요</b> — \"please do … for me\". 전하다 → 전해 주세요 — please pass it on. 서류 — documents."],
  e117: ["Предложение: <b>-(으)ㄹ까요?</b> — «давайте …?». Согласие: 좋아요, 같이 먹어요.", "Suggestion: <b>-(으)ㄹ까요?</b> — \"shall we …?\". To agree: 좋아요, 같이 먹어요."],
  e118: ["Обещание: <b>-(으)ㄹ게요</b> — «я сделаю». 끝낼게요 — закончу.", "Promise: <b>-(으)ㄹ게요</b> — \"I will\". 끝낼게요 — I'll finish it."],
  e119: ["Пару обуви или носков считают словом <b>켤레</b>. 벌 — комплект одежды, 권 — книги, 마리 — животные.", "A pair of shoes or socks takes <b>켤레</b>. 벌 — suits of clothing, 권 — books, 마리 — animals."],
  e120: ["Животных считают словом <b>마리</b>: 고양이 두 마리 — две кошки. Людей — 명.", "Animals take the counter <b>마리</b>: 고양이 두 마리 — two cats. People take 명."],
  e121: ["Книги считают словом <b>권</b>. 장 — листы, 대 — машины, 잔 — чашки, стаканы.", "Books take the counter <b>권</b>. 장 — sheets, 대 — vehicles, 잔 — cups."],
  e122: ["<b>건강 검진</b> — медосмотр. «Накануне с 9 вечера ничего не ешьте»: <b>드시다</b> — есть (вежливо).", "<b>건강 검진</b> — health check-up. \"Don't eat anything from 9 p.m. the night before\": <b>드시다</b> — to eat (honorific)."],
  e123: ["<b>잔업 수당</b> — доплата за сверхурочные: 300 000 вон. 기본급 — оклад, 세금 — налог, 명세서 — расчётный лист.", "<b>잔업 수당</b> — overtime pay: 300,000 won. 기본급 — base pay, 세금 — tax, 명세서 — pay slip."],
  e124: ["Сначала не мог есть из-за остроты, а <b>сейчас</b> больше всего любит 김치찌개. 맵다 — острый.", "At first the food was too spicy, but <b>now</b> 김치찌개 is his favourite. 맵다 — spicy."],
  e125: ["После въезда нужно зарегистрироваться <b>в течение 90 дней</b>. 근로자 — работник, 출입국 사무소 — миграционная служба.", "After entering Korea you must register <b>within 90 days</b>. 근로자 — worker, 출입국 사무소 — immigration office."],
  e126: ["Машина, которая поднимает и перевозит тяжёлые грузы, — <b>지게차</b> (погрузчик). 냉장고 — холодильник.", "A machine that lifts and moves heavy loads — <b>지게차</b> (forklift). 냉장고 — refrigerator."],
  e127: ["Машина для стирки — <b>세탁기</b>. 전자레인지 — микроволновка, 선풍기 — вентилятор.", "A machine for washing clothes — <b>세탁기</b>. 전자레인지 — microwave, 선풍기 — electric fan."],
  e128: ["Корейцы спрашивают возраст, потому что <b>от возраста зависит форма речи</b> (вежливость). -에 따라 — в зависимости от.", "Koreans ask your age because <b>the way you speak depends on age</b> (politeness). -에 따라 — depending on."],
  e129: ["<b>트럭</b> — грузовик. 🚌 버스 — автобус, 🚲 자전거 — велосипед, 🚑 구급차 — скорая.", "<b>트럭</b> — truck. 🚌 버스 — bus, 🚲 자전거 — bicycle, 🚑 구급차 — ambulance."],
  e130: ["<b>소</b> (so) — корова. 🐖 돼지 — свинья, 🐔 닭 — курица, 🐟 물고기 — рыба.", "<b>소</b> (so) — cow. 🐖 돼지 — pig, 🐔 닭 — chicken, 🐟 물고기 — fish."],
  e131: ["<b>생선</b> (saengseon) — рыба (как еда). 🍎 사과 — яблоко, 🥚 계란 — яйцо, 🍞 빵 — хлеб.", "<b>생선</b> (saengseon) — fish (as food). 🍎 사과 — apple, 🥚 계란 — egg, 🍞 빵 — bread."],
  e132: ["<b>우산</b> (usan) — зонт. 👓 안경 — очки, 🧢 모자 — кепка, 🧦 양말 — носки.", "<b>우산</b> (usan) — umbrella. 👓 안경 — glasses, 🧢 모자 — cap, 🧦 양말 — socks."],
  e133: ["<b>무슨 일</b> — какая работа? В ответе — род занятий: делаю станки на заводе.", "<b>무슨 일</b> — what kind of work? The answer names the job: I make machines at a factory."],
  e134: ["<b>시간 있어요?</b> — «Вы свободны?». Ответ: 네, 토요일은 괜찮아요 — в субботу могу.", "<b>시간 있어요?</b> — \"Are you free?\". Answer: 네, 토요일은 괜찮아요 — Saturday works."],
  e135: ["Опыт: <b>-아/어 본 적이 있다</b> — «доводилось …». Ответ в той же форме.", "Experience: <b>-아/어 본 적이 있다</b> — \"have done … before\". The answer uses the same form."],
  e136: ["<b>왜</b> — почему? В ответе причина: <b>-아/어서요</b> — «потому что …».", "<b>왜</b> — why? The answer gives a reason: <b>-아/어서요</b> — \"because …\"."],
  e137: ["Разбит экран телефона, нужен ремонт — <b>수리점</b> (мастерская). 깨지다 — разбиться, 고치다 — чинить.", "A cracked phone screen that needs fixing — <b>수리점</b> (repair shop). 깨지다 — to break, 고치다 — to fix."],
  e138: ["<b>출구</b> — выход, <b>호선</b> — линия метро, <b>갈아타다</b> — пересаживаться. Это <b>지하철역</b>.", "<b>출구</b> — exit, <b>호선</b> — subway line, <b>갈아타다</b> — to transfer. It's a <b>지하철역</b> (subway station)."],
  e139: ["<b>베이다</b> — порезаться. Мужчина слегка порезал руку. 입원하다 — лечь в больницу.", "<b>베이다</b> — to get cut. The man cut his hand slightly. 입원하다 — to be hospitalised."],
  e140: ["8:00 → 7:30: начало работы <b>на 30 минут раньше</b>. <b>빨라지다</b> — становиться раньше, 바뀌다 — меняться.", "8:00 → 7:30: work starts <b>30 minutes earlier</b>. <b>빨라지다</b> — to become earlier, 바뀌다 — to change."],
  e141: ["Позвонила сказать, что <b>опоздает</b>: сломался автобус. <b>-(으)ㄹ 것 같다</b> — «кажется, …».", "She called to say she'll <b>be late</b> because the bus broke down. <b>-(으)ㄹ 것 같다</b> — \"it seems …\"."],
  e142: ["Снимать обувь, есть после старших — это <b>예절</b> (этикет). 어른 — старший.", "Taking off shoes, eating after elders — that's <b>예절</b> (etiquette). 어른 — elder."],
  e143: ["Сортировка и вынос мусора — <b>쓰레기 버리기</b>. 종류별로 — по видам, 봉투 — пакет.", "Sorting and throwing out rubbish — <b>쓰레기 버리기</b>. 종류별로 — by type, 봉투 — bag."],
  e144: ["<b>오랜만이에요</b> — «Давно не виделись». <b>잘 지냈어요?</b> — «Как поживали?» → 네, 잘 지냈어요.", "<b>오랜만이에요</b> — \"Long time no see\". <b>잘 지냈어요?</b> — \"How have you been?\" → 네, 잘 지냈어요."],
  e145: ["Уезжающему говорят <b>잘 다녀오세요</b> (счастливо съездить). 휴가 — отпуск.", "To someone leaving on a trip: <b>잘 다녀오세요</b> (have a good trip). 휴가 — vacation."],
  e146: ["<b>불편하다</b> — неудобно; врач спрашивает «Что вас беспокоит?». Ответ: 허리가 아파요 — болит поясница.", "<b>불편하다</b> — uncomfortable; a doctor asks \"What's bothering you?\". Answer: 허리가 아파요 — my lower back hurts."],
  e147: ["<b>벽돌</b> — кирпич (стройка). 나무 — дерево, 유리 — стекло, 종이 — бумага.", "<b>벽돌</b> — brick (construction). 나무 — wood, 유리 — glass, 종이 — paper."],
  e148: ["<b>톱</b> — пила. 망치 — молоток, 삽 — лопата, 칼 — нож.", "<b>톱</b> — saw. 망치 — hammer, 삽 — shovel, 칼 — knife."],
  e149: ["<b>배추</b> — пекинская капуста (из неё делают кимчи). 고추 — перец, 마늘 — чеснок, 감자 — картофель.", "<b>배추</b> — napa cabbage (used for kimchi). 고추 — chili pepper, 마늘 — garlic, 감자 — potato."],
  e150: ["<b>관계자 외 출입 금지</b> — «Посторонним вход воспрещён». 관계자 — причастный сотрудник, 외 — кроме.", "<b>관계자 외 출입 금지</b> — \"Authorised personnel only\". 관계자 — staff concerned, 외 — except."],
  e151: ["<b>안전제일</b> — «Безопасность прежде всего». 제일 — самый, первый. Самый частый плакат на заводах.", "<b>안전제일</b> — \"Safety first\". 제일 — first, most. The most common sign in factories."],
  e152: ["<b>분리수거</b> — раздельный сбор мусора (пластик, бумага, стекло). 나누다 — разделять.", "<b>분리수거</b> — recycling by type (plastic, paper, glass). 나누다 — to divide."],
  e153: ["Неправильный глагол на ㄷ: <b>듣다</b> + 으세요 → ㄷ меняется на ㄹ → <b>들으세요</b> (слушайте). 드세요 — ешьте.", "ㄷ-irregular: <b>듣다</b> + 으세요 → ㄷ becomes ㄹ → <b>들으세요</b> (please listen). 드세요 — please eat."],
  e154: ["Услуга старшему: <b>-아/어 드리다</b> — «сделать для» (вежливо). 들다 → 들어 드릴게요 — я понесу.", "Doing something for someone: <b>-아/어 드리다</b> (humble). 들다 → 들어 드릴게요 — I'll carry it for you."],
  e155: ["Неправильный глагол на ㅂ: <b>돕다</b> → <b>도와</b> (ㅂ → 오/우). 도와 주다 — помогать.", "ㅂ-irregular: <b>돕다</b> → <b>도와</b> (ㅂ → 오/우). 도와 주다 — to help."],
  e156: ["Неправильный глагол на ㅅ: <b>낫다</b> (выздоравливать) + 으면 → ㅅ выпадает → <b>나으면</b>. 낳다 — рожать (другое слово!).", "ㅅ-irregular: <b>낫다</b> (to recover) + 으면 → ㅅ drops → <b>나으면</b>. 낳다 means to give birth (a different word!)."],
  e157: ["Неправильный глагол на 르: <b>모르다</b> + 아서 → <b>몰라서</b> (так как не знал). Так же: 빠르다 → 빨라요.", "르-irregular: <b>모르다</b> + 아서 → <b>몰라서</b> (because I didn't know). Likewise: 빠르다 → 빨라요."],
  e158: ["<b>아직</b> — ещё (с отрицанием: ещё не …). 벌써/이미 — уже.", "<b>아직</b> — yet/still (with a negative: not yet). 벌써/이미 — already."],
  e159: ["Нужно будущее: <b>이따가</b> — попозже. 아까 — только что (прошлое), 어제 — вчера.", "A future time is needed: <b>이따가</b> — later today. 아까 — a while ago, 어제 — yesterday."],
  e160: ["<b>월세</b> — ежемесячная аренда. «Сколько?» — ответ ценой. 보증금 — залог, 집주인 — хозяин.", "<b>월세</b> — monthly rent. \"How much?\" needs a price. 보증금 — deposit, 집주인 — landlord."],
  e161: ["<b>조퇴</b> — уход с работы раньше. Разрешение: 집에 가서 푹 쉬세요 — идите домой и хорошенько отдохните.", "<b>조퇴</b> — leaving work early. To allow it: 집에 가서 푹 쉬세요 — go home and get some rest."],
  e162: ["<b>주 5일</b> — 5 дней в неделю. <b>근로 계약서</b> — трудовой договор, 계약 기간 — срок договора.", "<b>주 5일</b> — 5 days a week. <b>근로 계약서</b> — employment contract, 계약 기간 — contract term."],
  e163: ["В комнате готовить нельзя — только <b>на кухне на 1 этаже</b>. 규칙 — правила, 부엌 — кухня.", "No cooking in rooms — only <b>in the 1st-floor kitchen</b>. 규칙 — rules, 부엌 — kitchen."],
  e164: ["<b>산재 보험</b> — страховка от несчастных случаев на производстве. Иностранцам тоже положена. 알리다 — сообщать.", "<b>산재 보험</b> — workers' accident insurance. Foreign workers are covered too. 알리다 — to inform."],
  e165: ["<b>장마</b> — сезон летних дождей (около месяца). 항상 — всегда, 가지고 다니다 — носить с собой.", "<b>장마</b> — the summer monsoon (about a month). 항상 — always, 가지고 다니다 — to carry around."],
  e166: ["Чтобы положить или снять деньги в банке, — <b>통장</b> (сберкнижка). 영수증 — чек, 여권 — паспорт.", "To deposit or withdraw money at a bank — <b>통장</b> (bankbook). 영수증 — receipt, 여권 — passport."],
  e167: ["Бумага от врача — <b>처방전</b> (рецепт). 신분증 — удостоверение личности.", "The paper a doctor writes — <b>처방전</b> (prescription). 신분증 — ID card."],
  e168: ["Главная мысль: <b>не бойтесь ошибок, говорите</b>. 실력이 늘다 — уровень растёт, -게 되다 — в итоге.", "Main idea: <b>don't fear mistakes, keep speaking</b>. 실력이 늘다 — skills improve, -게 되다 — end up."],
  e169: ["<b>벽돌</b> (byeokdol) — кирпич. 🪵 나무 — дерево, 🪟 창문 — окно, 📦 상자 — коробка.", "<b>벽돌</b> (byeokdol) — brick. 🪵 나무 — wood, 🪟 창문 — window, 📦 상자 — box."],
  e170: ["<b>배추</b> (baechu) — пекинская капуста. 🥕 당근 — морковь, 🌽 옥수수 — кукуруза.", "<b>배추</b> (baechu) — napa cabbage. 🥕 당근 — carrot, 🌽 옥수수 — corn."],
  e171: ["<b>비행기</b> (bihaenggi) — самолёт. 🚢 배 — корабль, 🚗 자동차 — автомобиль.", "<b>비행기</b> (bihaenggi) — airplane. 🚢 배 — ship, 🚗 자동차 — car."],
  e172: ["<b>전구</b> (jeongu) — лампочка. 🔦 손전등 — фонарик, 🕯️ 초 — свеча, 🔌 플러그 — вилка.", "<b>전구</b> (jeongu) — light bulb. 🔦 손전등 — flashlight, 🕯️ 초 — candle, 🔌 플러그 — plug."],
  e173: ["<b>뭐가 필요해요?</b> — что нужно? В ответе документ: 외국인 등록증 — карта иностранца.", "<b>뭐가 필요해요?</b> — what's needed? The answer is a document: 외국인 등록증 — alien registration card."],
  e174: ["<b>결근</b> — неявка на работу. <b>왜</b> — почему? В ответе причина: была температура, ходил в больницу.", "<b>결근</b> — absence from work. <b>왜</b> — why? The answer gives a reason: I had a high fever and went to hospital."],
  e175: ["<b>언제까지</b> — до какого срока? Ответ: 금요일까지 — до пятницы.", "<b>언제까지</b> — by when? The answer is a deadline: 금요일까지 — by Friday."],
  e176: ["<b>뭐가 제일 힘들어요?</b> — что труднее всего? Ответ: 한국어가 제일 어려워요 — корейский язык.", "<b>뭐가 제일 힘들어요?</b> — what's hardest? Answer: 한국어가 제일 어려워요 — Korean is the hardest."],
  e177: ["<b>환전</b> — обмен валюты: доллары на воны. Это <b>은행</b> (банк). 바꾸다 — менять.", "<b>환전</b> — currency exchange: dollars to won. It's a <b>은행</b> (bank). 바꾸다 — to change."],
  e178: ["Объясняют, как принимать лекарство, — <b>약국</b> (аптека). 하루에 세 번 — три раза в день.", "Instructions for taking medicine — <b>약국</b> (pharmacy). 하루에 세 번 — three times a day."],
  e179: ["<b>휘발유</b> — бензин, <b>가득</b> — полный бак. Это <b>주유소</b> (заправка). 주차장 — парковка.", "<b>휘발유</b> — gasoline, <b>가득</b> — full. It's a <b>주유소</b> (gas station). 주차장 — parking lot."],
  e180: ["Со следующей недели на заводе много работы, поэтому <b>работают и в субботу</b>. 한가하다 — свободный.", "From next week the factory is busy, so <b>they work on Saturdays too</b>. 한가하다 — not busy."],
  e181: ["<b>-(으)ㄹ 줄 알다</b> — «уметь». Мужчина видит станок впервые и не умеет им пользоваться.", "<b>-(으)ㄹ 줄 알다</b> — \"know how to\". The man is seeing the machine for the first time and can't use it."],
  e182: ["<b>닦다</b> — вытирать. На полу масло, мужчина сейчас вытрет. 기름 — масло, 넘어지다 — упасть.", "<b>닦다</b> — to wipe. There's oil on the floor; the man will wipe it now. 기름 — oil, 넘어지다 — to fall over."],
  e183: ["У неё температура, нужно в больницу: позвонила, чтобы <b>отпроситься по болезни</b>. 연락 — связь.", "She has a fever and must go to hospital: she called <b>to take a sick day</b>. 연락 — contact."],
  e184: ["<b>태풍</b> — тайфун. Занести вещи, закрыть окна — <b>подготовка к тайфуну</b>.", "<b>태풍</b> — typhoon. Moving things inside and shutting windows — <b>preparing for a typhoon</b>."],
  e185: ["Главный совет: <b>спрашивайте, если не знаете</b>. 물어보다 — расспросить, 실수 — ошибка.", "The key advice: <b>ask when you don't know</b>. 물어보다 — to ask, 실수 — mistake."],
  e186: ["<b>회식</b> — ужин коллектива. Согласие на приглашение: 네, 좋아요. 같이 가요.", "<b>회식</b> — a team dinner with coworkers. Accepting: 네, 좋아요. 같이 가요."],
  t001: ["<b>도서관</b> — библиотека. 책을 빌리다 — брать книгу. 병원 — больница, 식당 — столовая, 우체국 — почта.", "<b>도서관</b> — library. 책을 빌리다 — to borrow a book. 병원 — hospital, 식당 — restaurant, 우체국 — post office."],
  t002: ["С яблоком (사과) используется <b>먹다</b> — есть. 읽다 — читать, 입다 — надевать, 타다 — ехать (на транспорте).", "Apples (사과) take <b>먹다</b> — to eat. 읽다 — to read, 입다 — to wear, 타다 — to ride."],
  t003: ["언니 — старшая сестра (для девушки), 남동생 — младший брат. Значит, речь о <b>가족</b> (семья). 나이 — возраст, 직업 — профессия, 취미 — хобби.", "언니 — older sister (said by a woman), 남동생 — younger brother. So it's about <b>가족</b> (family). 나이 — age, 직업 — job, 취미 — hobby."],
  t004: ["<b>어제</b> (вчера) — нужно прошедшее время: <b>-았/었어요</b>. 보다 → 봤어요 (смотрели). 볼 거예요 — будущее.", "<b>어제</b> (yesterday) needs the past: <b>-았/었어요</b>. 보다 → 봤어요 (watched). 볼 거예요 is future."],
  t005: ["Вопрос: «Когда у вас день рождения?» На <b>언제</b> (когда) отвечают датой: <b>5월 3일이에요</b> — 3 мая.", "\"When is your birthday?\" — <b>언제</b> (when) is answered with a date: <b>5월 3일이에요</b> — 3 May."],
  t006: ["«Добро пожаловать. Что вам? Один айс-американо, пожалуйста». Заказывают кофе — значит, <b>카페</b>. 은행 — банк, 학교 — школа.", "\"Welcome. What can I get you? One iced americano, please.\" Ordering coffee, so it's a <b>카페</b>. 은행 — bank, 학교 — school."],
  t007: ["«На выходных обычно занимаюсь спортом в парке. Но на этой неделе шёл дождь, поэтому отдыхал дома». <b>그런데</b> — но, <b>비가 와서</b> — так как шёл дождь.", "\"At weekends I usually exercise in the park. But this week it rained, so I rested at home.\" <b>그런데</b> — but, <b>비가 와서</b> — because it rained."],
  t008: ["Причина <b>-아서/어서</b>: «Было жарко, поэтому открыл окно». 덥다 — неправильный глагол: ㅂ → 우, поэтому <b>더워서</b>.", "Reason <b>-아서/어서</b>: \"It was hot, so I opened the window.\" 덥다 is irregular: ㅂ → 우, so <b>더워서</b>."],
  t009: ["여름 — лето, 겨울 — зима. Значит, речь о <b>계절</b> (время года).", "여름 — summer, 겨울 — winter. So it's about <b>계절</b> (seasons)."],
  t010: ["천 원 — 1000 вон, 이천 원 — 2000 вон. Речь о ценах: <b>가격</b> (цена).", "천 원 — 1,000 won, 이천 원 — 2,000 won. It's about <b>가격</b> (price)."],
  t011: ["<b>배가 고프다</b> — быть голодным. Едят <b>밥</b> (еду, рис). С 물 (вода) используется 마시다 (пить).", "<b>배가 고프다</b> — to be hungry. You eat <b>밥</b> (rice/a meal). 물 (water) takes 마시다 (to drink)."],
  t012: ["Пьёт три чашки в день — значит, любит <b>아주</b> (очень). 조금 — немного, 안/못 — отрицание.", "Three cups a day means he likes it <b>아주</b> (a lot). 조금 — a little, 안/못 — negation."],
  t013: ["Завтра экзамен, в библиотеке — <b>공부할 거예요</b> (буду заниматься). <b>그래서</b> — поэтому.", "Exam tomorrow, in the library — <b>공부할 거예요</b> (I'll study). <b>그래서</b> — so."],
  t014: ["Воскресенье — <b>주말</b> (выходной), в этот день работают только до <b>18:00</b>. <b>평일</b> — будни. Внимание: «맞지 않는 것» — нужно найти НЕверное!", "Sunday is <b>주말</b> (weekend), open only until <b>6 pm</b>. <b>평일</b> — weekdays. Note: \"맞지 않는 것\" means find the one that is NOT true!"],
  t015: ["<b>멀다</b> — далеко, <b>-쯤</b> — примерно, <b>걸리다</b> — занимать (время). До работы около часа.", "<b>멀다</b> — far, <b>-쯤</b> — about, <b>걸리다</b> — to take (time). It takes about an hour to work."],
  t016: ["<b>키가 크다</b> — высокий. Хорошо играет в баскетбол — значит, высокий. С 키 используются 크다/작다, а не 길다/짧다.", "<b>키가 크다</b> — tall. Good at basketball, so tall. 키 takes 크다/작다, not 길다/짧다."],
  t017: ["<b>-와/과 같이</b> — «вместе с». 친구 оканчивается на гласную → <b>와</b>. После согласной — 과: 선생님과.", "<b>-와/과 같이</b> — \"together with\". 친구 ends in a vowel → <b>와</b>. After a consonant: 과 (선생님과)."],
  t018: ["Главная мысль: <b>한국 음식을 배우고 싶습니다</b> — хочу научиться корейской кухне. Остальных вариантов в тексте нет.", "Main idea: <b>한국 음식을 배우고 싶습니다</b> — I want to learn Korean cooking. The other options aren't in the text."],
  t019: ["Оба значат «поэтому», но перед приказом (-세요) используется только <b>그러니까</b>. После 그래서 приказ не ставят — любимая ловушка TOPIK!", "Both mean \"so\", but only <b>그러니까</b> can come before a command (-세요). 그래서 can't be followed by a command — a favourite TOPIK trap!"],
  t020: ["«Еду приготовлю сам, просто приходите» — гостям <b>не нужно</b> приносить еду. <b>초대하다</b> — приглашать.", "\"I'll prepare the food, just come\" — guests <b>don't need</b> to bring food. <b>초대하다</b> — to invite."],
  t021: ["«Вы студент?» — <b>네, 학생이에요</b>. После 아니요 должно быть отрицание: 아니요, 학생이 아니에요.", "\"Are you a student?\" — <b>네, 학생이에요</b>. After 아니요 you need a negative: 아니요, 학생이 아니에요."],
  t022: ["На <b>있어요?</b> («есть?») отвечают <b>있어요/없어요</b>: 네, 사과가 있어요.", "<b>있어요?</b> (\"do you have…?\") is answered with <b>있어요/없어요</b>: 네, 사과가 있어요."],
  t023: ["<b>누구하고</b> — с кем? В ответе нужен человек: <b>친구하고</b> — с другом.", "<b>누구하고</b> — with whom? The answer needs a person: <b>친구하고</b> — with a friend."],
  t024: ["Книгу <b>돌려주다</b> (возвращают) — значит, её брали: <b>도서관</b> (библиотека). 서점 — книжный магазин, там книги покупают.", "You <b>돌려주다</b> (return) the book, so it was borrowed: <b>도서관</b> (library). 서점 is a bookshop, where you buy books."],
  t025: ["<b>봄</b> — весна, <b>꽃이 피다</b> — цветы распускаются. Речь о <b>계절</b> (время года).", "<b>봄</b> — spring, <b>꽃이 피다</b> — flowers bloom. It's about <b>계절</b> (seasons)."],
  t026: ["Фотографировать в свободное время — это <b>취미</b> (хобби). <b>-(으)면</b> — «если».", "Taking photos in free time is a <b>취미</b> (hobby). <b>-(으)면</b> — \"if/when\"."],
  t027: ["<b>약속</b> — встреча, <b>바꾸다</b> — менять. Встречу перенесли с 3 на 4 часа. <b>여보세요</b> — «алло».", "<b>약속</b> — appointment, <b>바꾸다</b> — to change. The meeting moved from 3 to 4. <b>여보세요</b> — \"hello\" on the phone."],
  t028: ["На «Приятного аппетита!» отвечают <b>잘 먹겠습니다</b> (спасибо, с удовольствием поем). После еды — 잘 먹었습니다.", "When told \"Enjoy your meal!\", reply <b>잘 먹겠습니다</b> (thank you, I'll enjoy it). After eating: 잘 먹었습니다."],
  t029: ["«Извините за опоздание». — <b>괜찮아요</b> (ничего страшного). <b>죄송합니다</b> — извините (вежливо).", "\"Sorry I'm late.\" — <b>괜찮아요</b> (that's okay). <b>죄송합니다</b> — I'm sorry (formal)."],
  t030: ["«Как вас подстричь? — Коротко, пожалуйста». — парикмахерская (<b>미용실</b>). <b>자르다</b> — резать, стричь, <b>짧게</b> — коротко.", "\"How would you like your hair? — Short, please.\" — a hair salon (<b>미용실</b>). <b>자르다</b> — to cut, <b>짧게</b> — short."],
  t031: ["의사 — врач. Речь о профессии: <b>직업</b>.", "의사 — doctor. It's about a job: <b>직업</b> (occupation)."],
  t032: ["빵 — хлеб, 밥 — рис, еда. Речь о <b>음식</b> (еде).", "빵 — bread, 밥 — rice, a meal. It's about <b>음식</b> (food)."],
  t033: ["Любимое занятие — <b>취미</b> (хобби). <b>-마다</b> — каждый (주말마다 — каждые выходные).", "A pastime — <b>취미</b> (hobby). <b>-마다</b> — every (주말마다 — every weekend)."],
  t034: ["3월 5일 — 5 марта. Месяц и число — <b>날짜</b> (дата). 요일 — день недели.", "3월 5일 — March 5. Month and day form a <b>날짜</b> (date). 요일 — day of the week."],
  t035: ["<b>맑다</b> — ясный. «Небо ясное» — <b>하늘</b>. 바다 — море, 눈 — снег, 비 — дождь.", "<b>맑다</b> — clear. \"The sky is clear\" — <b>하늘</b>. 바다 — sea, 눈 — snow, 비 — rain."],
  t036: ["Противопоставление: <b>그러나</b> — но. 그리고 — и, 그래서 — поэтому, 그러면 — тогда.", "Contrast: <b>그러나</b> — but. 그리고 — and, 그래서 — so, 그러면 — then."],
  t037: ["В библиотеке книги <b>빌리다</b> — берут на время. 입다 — надевать, 타다 — ехать, 마시다 — пить.", "At a library you <b>빌리다</b> (borrow) books. 입다 — wear, 타다 — ride, 마시다 — drink."],
  t038: ["Не может поднять, значит сумка <b>무겁다</b> — тяжёлая. 가볍다 — лёгкий, 들다 — поднимать.", "He can't lift it, so the bag is <b>무겁다</b> — heavy. 가볍다 — light, 들다 — to lift."],
  t039: ["<b>만나다</b> (встречаться) требует винительного падежа: 친구<b>를</b> 만나다. После гласной — 를.", "<b>만나다</b> (to meet) takes the object marker: 친구<b>를</b> 만나다. After a vowel, use 를."],
  t040: ["Место действия: <b>에서</b> — «в». Учу корейский в школе.", "Place of an action: <b>에서</b> — \"at\". I study Korean at school."],
  t041: ["<b>반</b> — половина: 세 시 반 — половина четвёртого (3:30). 일 — день, 월 — месяц, 년 — год.", "<b>반</b> — half: 세 시 반 — half past three. 일 — day, 월 — month, 년 — year."],
  t042: ["Занятия по <b>토요일</b> (субботам), не по воскресеньям. <b>무료</b> — бесплатно, 매주 — каждую неделю.", "Classes are on <b>토요일</b> (Saturday), not Sunday. <b>무료</b> — free, 매주 — every week."],
  t043: ["Магазин открывается в <b>오전 10시</b> (10 утра), а не в 9. <b>할인</b> — скидка, 영업시간 — часы работы.", "The shop opens at <b>오전 10시</b> (10 a.m.), not 9. <b>할인</b> — discount, 영업시간 — business hours."],
  t044: ["В тексте: «Море было очень красивым». С семьёй он хочет поехать в следующий раз. <b>지난주</b> — на прошлой неделе.", "The text says the sea was very beautiful. He wants to go with family next time. <b>지난주</b> — last week."],
  t045: ["<b>아침마다</b> = каждое утро. 근처 — поблизости, 산책 — прогулка, 기분이 좋다 — хорошее настроение.", "<b>아침마다</b> = every morning. 근처 — nearby, 산책 — a walk, 기분이 좋다 — to feel good."],
  t046: ["Главная мысль — в последнем предложении: дорамы помогают учить корейский. <b>도움이 되다</b> — помогать.", "The main idea is in the last sentence: dramas help with learning Korean. <b>도움이 되다</b> — to be helpful."],
  t047: ["Без завтрака нет сил: значит, <b>завтракать важно</b>. 힘이 없다 — нет сил.", "Without breakfast there's no energy, so <b>breakfast matters</b>. 힘이 없다 — to have no energy."],
  t048: ["<b>우리 집</b> — «наш дом», то есть дом автора записки. Мина — приглашённая гостья.", "<b>우리 집</b> — \"our house\", i.e. the writer's home. Mina is the invited guest."],
  t049: ["<b>있어요?</b> — есть? Ответ: 네, 있어요 или 아니요, 없어요. 이에요/아니에요 — для другого вопроса.", "<b>있어요?</b> — do you have? Answer 네, 있어요 or 아니요, 없어요. 이에요/아니에요 answer a different question."],
  t050: ["<b>어디에</b> — куда? В ответе место: 시장에 — на рынок.", "<b>어디에</b> — where to? The answer is a place: 시장에 — to the market."],
  t051: ["<b>언제</b> — когда? В ответе время: 작년에 — в прошлом году.", "<b>언제</b> — when? The answer is a time: 작년에 — last year."],
  t052: ["<b>무슨 음식</b> — какую еду? В ответе название блюда: 불고기.", "<b>무슨 음식</b> — what food? The answer names a dish: 불고기."],
  t053: ["Взять книгу на время и студенческий билет — <b>도서관</b> (библиотека). Если покупать — 서점.", "Borrowing a book and a student ID — <b>도서관</b> (library). Buying would be 서점."],
  t054: ["<b>표</b> (билеты) до Пусана — <b>기차역</b> (вокзал). 오만 원 — 50 000 вон.", "<b>표</b> (tickets) to Busan — <b>기차역</b> (train station). 오만 원 — 50,000 won."],
  t055: ["Встаю в 7, в 8 иду в школу — речь о <b>시간</b> (времени).", "Up at 7, school at 8 — it's about <b>시간</b> (time)."],
  t056: ["<b>얼마예요?</b> — сколько стоит? Речь о <b>가격</b> (цене). 한 개에 — за штуку.", "<b>얼마예요?</b> — how much is it? It's about <b>가격</b> (price). 한 개에 — each."],
  t057: ["Мужчина в выходные пойдёт в кино <b>с другом</b>. <b>-(으)ㄹ 거예요</b> — будущее время.", "The man will watch a film <b>with a friend</b> at the weekend. <b>-(으)ㄹ 거예요</b> — future tense."],
  t058: ["<b>감기에 걸리다</b> — простудиться. Женщина простудилась и поэтому не пошла в школу.", "<b>감기에 걸리다</b> — to catch a cold. The woman has a cold, so she didn't go to school."],
  t059: ["На поздравление отвечают <b>고마워요</b> (спасибо). 미안해요 — извините.", "Reply to congratulations with <b>고마워요</b> (thank you). 미안해요 — sorry."],
  t060: ["Уходящий говорит <b>안녕히 계세요</b> (оставайтесь с миром), остающийся — <b>안녕히 가세요</b> (счастливого пути).", "The person leaving says <b>안녕히 계세요</b> (stay well); the one staying replies <b>안녕히 가세요</b> (go well)."],
  t061: ["Автобус, метро — <b>교통</b> (транспорт).", "Bus, subway — <b>교통</b> (transport)."],
  t062: ["Где кто живёт — <b>장소</b> (место).", "Where people live — <b>장소</b> (place)."],
  t063: ["월요일 — понедельник, 화요일 — вторник: <b>요일</b> (день недели). Дата — 날짜 (3월 5일).", "월요일 — Monday, 화요일 — Tuesday: <b>요일</b> (day of the week). A date would be 날짜 (3월 5일)."],
  t064: ["스무 살 — 20 лет, 스물다섯 살 — 25 лет: <b>나이</b> (возраст). 살 — счётное слово для возраста.", "스무 살 — 20 years old, 스물다섯 살 — 25: <b>나이</b> (age). 살 — counter for age."],
  t065: ["<b>목이 마르다</b> — хотеть пить. 배가 고프다 — быть голодным.", "<b>목이 마르다</b> — to be thirsty. 배가 고프다 — to be hungry."],
  t066: ["В 7 утра — <b>일어나다</b> (вставать). 자다 — спать, 앉다 — садиться.", "At 7 in the morning — <b>일어나다</b> (to get up). 자다 — to sleep, 앉다 — to sit."],
  t067: ["Холодно — надевают <b>코트</b> (пальто). 반바지 — шорты, 수영복 — купальник, 선글라스 — тёмные очки.", "It's cold, so you wear a <b>코트</b> (coat). 반바지 — shorts, 수영복 — swimsuit, 선글라스 — sunglasses."],
  t068: ["Другу отправляют <b>편지</b> (письмо). <b>에게</b> — «кому» (человеку).", "You send a <b>편지</b> (letter) to a friend. <b>에게</b> — \"to\" (a person)."],
  t069: ["В универмаге туфли <b>사다</b> — покупают. 구두 — туфли, 백화점 — универмаг.", "At a department store you <b>사다</b> (buy) shoes. 구두 — dress shoes, 백화점 — department store."],
  t070: ["Ужин в 7 часов — <b>오후</b> (после полудня, вечером). 오전 — до полудня, 새벽 — рассвет.", "Dinner at 7 — <b>오후</b> (p.m.). 오전 — a.m., 새벽 — dawn."],
  t071: ["Сравнение: <b>N보다</b> — «чем N». Я ниже старшего брата.", "Comparison: <b>N보다</b> — \"than N\". I'm shorter than my older brother."],
  t072: ["Дать кому-то: <b>N에게 주다</b>. 에서 — место, 을 — винительный падеж.", "Give to someone: <b>N에게 주다</b>. 에서 marks a place, 을 the object."],
  t073: ["Бассейн закрывается <b>в 10 вечера</b>, в 11 плавать нельзя. 쉬는 날 — выходной.", "The pool closes <b>at 10 p.m.</b>, so you can't swim at 11. 쉬는 날 — closed day."],
  t074: ["Написано «подарки не приносите» — значит, подарок <b>не нужен</b>. 이사 — переезд.", "It says \"please don't bring gifts\", so a gift is <b>not needed</b>. 이사 — moving house."],
  t075: ["В тексте: катался на велосипеде и ел курицу (치킨). Ходил с другом, было очень интересно.", "The text says he rode a bike and ate chicken (치킨). He went with a friend and had a great time."],
  t076: ["<b>시험 기간</b> — сессия. Библиотека большая, книг много, тихо. 시끄럽다 — шумный.", "<b>시험 기간</b> — exam period. The library is big, has many books and is quiet. 시끄럽다 — noisy."],
  t077: ["<b>초대하다</b> — приглашать. Зовёт друзей домой и готовит для них.", "<b>초대하다</b> — to invite. He invites friends over and cooks for them."],
  t078: ["Главная мысль: <b>вести дневник полезно</b> — можно обдумать прошедший день. 일기 — дневник.", "Main idea: <b>keeping a diary is good</b> — you can reflect on your day. 일기 — diary."],
  t079: ["Главная мысль: <b>покупать только нужное</b>. 낭비 — растрата, -다고 — «потому что, мол».", "Main idea: <b>buy only what you need</b>. 낭비 — waste, -다고 — \"just because …\"."],
  t080: ["Собрание перенесли с 2 на <b>4</b>. 3 часа — время звонка. <b>-에서 -(으)로 바뀌다</b> — смениться с … на ….", "The meeting moved from 2 to <b>4</b>. 3 o'clock is when the call came. <b>-에서 -(으)로 바뀌다</b> — to change from … to …."],
  t081: ["«Поужинаю <b>с другом</b>». <b>-하고</b> — с, -쯤 — примерно.", "\"I'll have dinner <b>with a friend</b>.\" <b>-하고</b> — with, -쯤 — about."],
  t082: ["Где книги <b>покупают</b> — <b>서점</b> (книжный магазин). Где берут почитать — 도서관.", "Where you <b>buy</b> books — <b>서점</b> (bookshop). Where you borrow them — 도서관."],
  t083: ["<b>차갑다</b> — холодный. Вопрос о качестве, ответ тем же словом: 네, 차가워요.", "<b>차갑다</b> — cold. The question is about a quality, so answer with it: 네, 차가워요."],
  t084: ["<b>있어요?</b> — есть? → 네, 있어요 / 아니요, 없어요.", "<b>있어요?</b> — do you have? → 네, 있어요 / 아니요, 없어요."],
  t085: ["<b>몇 살</b> — сколько лет? Возраст — корейскими числами и <b>살</b>: 스물두 살 — 22 года.", "<b>몇 살</b> — how old? Age uses native numbers and <b>살</b>: 스물두 살 — 22."],
  t086: ["<b>누구를</b> — кого? В ответе человек: 친구를 — друга.", "<b>누구를</b> — whom? The answer is a person: 친구를 — my friend."],
  t087: ["<b>어떻게</b> — как (на чём)? В ответе способ: 버스를 타고 — на автобусе.", "<b>어떻게</b> — how? The answer gives the means: 버스를 타고 — by bus."],
  t088: ["Отправка письма, <b>우표</b> (марка) — <b>우체국</b> (почта).", "Sending a letter, <b>우표</b> (stamp) — <b>우체국</b> (post office)."],
  t089: ["<b>층</b> — этаж, <b>누르다</b> — нажимать: кнопка этажа — <b>엘리베이터</b> (лифт).", "<b>층</b> — floor, <b>누르다</b> — to press: pressing a floor button — <b>엘리베이터</b> (elevator)."],
  t090: ["Где продают хлеб — <b>빵집</b> (пекарня). 꽃집 — цветочный магазин.", "Where bread is sold — <b>빵집</b> (bakery). 꽃집 — flower shop."],
  t091: ["<b>봄</b> — весна: речь о <b>계절</b> (времени года). 꽃이 피다 — цветы распускаются.", "<b>봄</b> — spring: it's about <b>계절</b> (season). 꽃이 피다 — flowers bloom."],
  t092: ["Договариваются о времени встречи — <b>약속</b> (встреча, договорённость).", "Arranging a time to meet — <b>약속</b> (appointment)."],
  t093: ["Кровать, стол, окно — речь о <b>방</b> (комнате).", "Bed, desk, window — it's about a <b>방</b> (room)."],
  t094: ["Женщина не пьёт кофе и просит <b>녹차</b> (зелёный чай). <b>-(으)ㄹ래요?</b> — «будете …?».", "The woman doesn't drink coffee and asks for <b>녹차</b> (green tea). <b>-(으)ㄹ래요?</b> — \"would you like …?\"."],
  t095: ["<b>옆에</b> — рядом. Банк рядом с почтой. 근처 — поблизости.", "<b>옆에</b> — next to. The bank is next to the post office. 근처 — nearby."],
  t096: ["<b>방학</b> — каникулы. Женщина на каникулах ездила домой и виделась с семьёй.", "<b>방학</b> — school vacation. The woman went home and saw her family."],
  t097: ["Перед едой говорят <b>잘 먹겠습니다</b>; хозяин отвечает <b>맛있게 드세요</b> (приятного аппетита).", "Before eating people say <b>잘 먹겠습니다</b>; the host replies <b>맛있게 드세요</b> (enjoy your meal)."],
  t098: ["По телефону: «Это квартира учителя Кима?» → <b>네, 그런데요. 누구세요?</b> — «Да. А кто спрашивает?». 댁 — дом (вежл.).", "On the phone: \"Is this Mr Kim's home?\" → <b>네, 그런데요. 누구세요?</b> — \"Yes. Who's calling?\". 댁 — home (honorific)."],
  t099: ["Спросили, где находится, — показывают дорогу: <b>저쪽으로 가세요</b> (идите туда). 실례지만 — извините, …", "Asked for a location, you give directions: <b>저쪽으로 가세요</b> (go that way). 실례지만 — excuse me, but …"],
  t100: ["Женщина хочет купить <b>운동화</b> (кроссовки). 찾다 — искать, 사이즈 — размер.", "The woman wants to buy <b>운동화</b> (sneakers). 찾다 — to look for, 사이즈 — size."],
  t101: ["Плавание, теннис — <b>운동</b> (спорт).", "Swimming, tennis — <b>운동</b> (sport, exercise)."],
  t102: ["눈 — глаза, 코 — нос: <b>얼굴</b> (лицо). Здесь 눈 — не снег, а глаза.", "눈 — eyes, 코 — nose: <b>얼굴</b> (face). Here 눈 means eyes, not snow."],
  t103: ["Корейский, японский — <b>외국어</b> (иностранный язык).", "Korean, Japanese — <b>외국어</b> (foreign languages)."],
  t104: ["Дождь, ветер — <b>날씨</b> (погода). 바람이 불다 — дует ветер.", "Rain, wind — <b>날씨</b> (weather). 바람이 불다 — the wind blows."],
  t105: ["<b>보다</b> — смотреть: 영화를 보다. Музыку — 듣다, песню — 부르다, письмо — 읽다/쓰다.", "<b>보다</b> — to watch: 영화를 보다. Music — 듣다, a song — 부르다, a letter — 읽다/쓰다."],
  t106: ["Жарко — включают <b>에어컨</b> (кондиционер). 난로 — обогреватель. 켜다 — включать.", "It's hot, so you turn on the <b>에어컨</b> (air conditioner). 난로 — heater. 켜다 — to turn on."],
  t107: ["Добавил сахар — значит, кофе <b>쓰다</b> — горький. 달다 — сладкий, 짜다 — солёный, 맵다 — острый.", "Sugar was added, so the coffee is <b>쓰다</b> — bitter. 달다 — sweet, 짜다 — salty, 맵다 — spicy."],
  t108: ["Помещается много вещей — сумка <b>크다</b> (большая). 들어가다 — помещаться.", "Lots of things fit, so the bag is <b>크다</b> (big). 들어가다 — to fit in."],
  t109: ["Каждое утро в парке — <b>걷다</b> (гулять пешком). 걷다 — 걸어요 (неправильный на ㄷ).", "Every morning in the park — <b>걷다</b> (to walk). 걷다 — 걸어요 (ㄷ-irregular)."],
  t110: ["Противопоставление: сегодня занят, <b>но</b> завтра свободен — <b>하지만</b>.", "Contrast: busy today, <b>but</b> free tomorrow — <b>하지만</b>."],
  t111: ["Место: <b>앞</b> — перед. Метро перед банком. 위 — на, 안/속 — внутри.", "Location: <b>앞</b> — in front of. The subway station is in front of the bank. 위 — on top, 안/속 — inside."],
  t112: ["Место действия: <b>에서</b>. Играли у друга дома. 에 — направление или место нахождения.", "Place of action: <b>에서</b>. We hung out at a friend's place. 에 marks direction or location of being."],
  t113: ["Продолжительность: <b>동안</b> — в течение. Занимаюсь спортом в течение часа.", "Duration: <b>동안</b> — for. I exercise for one hour."],
  t114: ["<b>배달: 안 됨</b> — доставки нет, заказать домой нельзя. 주차 — парковка.", "<b>배달: 안 됨</b> — no delivery, so you can't order food home. 주차 — parking."],
  t115: ["Фильм начинается в <b>오후 7시 30분</b> — в 19:30, а не утром. 좌석 — место.", "The film starts at <b>오후 7시 30분</b> — 7:30 p.m., not in the morning. 좌석 — seat."],
  t116: ["Сосед по комнате — китаец, <b>очень приветливый</b>. 룸메이트 — сосед, 친절하다 — доброжелательный.", "The roommate is Chinese and <b>very kind</b>. 룸메이트 — roommate, 친절하다 — kind."],
  t117: ["Ходит на курсы два раза в неделю. <b>-고 있다</b> — длительное действие, 치다 — играть (на пианино).", "Goes to lessons twice a week. <b>-고 있다</b> — ongoing action, 치다 — to play (piano)."],
  t118: ["<b>생신</b> — день рождения (вежл.). Купил маме цветы и торт, вечером идут в ресторан.", "<b>생신</b> — birthday (honorific). He bought flowers and a cake for his mother; dinner out tonight."],
  t119: ["Главная мысль: <b>хочет рано вставать и заниматься спортом</b>. <b>-(으)려고 하다</b> — намерение.", "Main idea: <b>wants to get up early and exercise</b>. <b>-(으)려고 하다</b> — intention."],
  t120: ["<b>-(으)면 좋겠다</b> — «хорошо бы» (желание). Главное: хочет завести корейских друзей. 사귀다 — дружить.", "<b>-(으)면 좋겠다</b> — \"I wish\". Main idea: wants to make Korean friends. 사귀다 — to make friends."],
  t121: ["<b>1월 3일부터 다시 이용할 수 있습니다</b> — снова работает с 3 января. 이용하다 — пользоваться.", "<b>1월 3일부터 다시 이용할 수 있습니다</b> — open again from January 3. 이용하다 — to use."],
  t122: ["<b>결혼식</b> — свадьба. 초대장 — приглашение, 졸업식 — выпускной, 입학식 — церемония поступления.", "<b>결혼식</b> — wedding. 초대장 — invitation, 졸업식 — graduation, 입학식 — entrance ceremony."],
  t123: ["Вопрос в прошедшем (<b>했어요?</b>) — ответ тоже: 네, 숙제를 했어요.", "A past-tense question (<b>했어요?</b>) gets a past-tense answer: 네, 숙제를 했어요."],
  t124: ["Отрицательный ответ на <b>있어요?</b> — <b>없어요</b> (нет).", "The negative answer to <b>있어요?</b> is <b>없어요</b> (I don't have one)."],
  t125: ["<b>뭐</b> — что? и прошедшее время: 비빔밥을 먹었어요.", "<b>뭐</b> — what? in the past tense: 비빔밥을 먹었어요."],
  t126: ["<b>얼마나 걸려요?</b> — сколько занимает? Ответ: 30분쯤 — около 30 минут.", "<b>얼마나 걸려요?</b> — how long does it take? Answer: 30분쯤 — about 30 minutes."],
  t127: ["<b>무슨 색</b> — какой цвет? Ответ: 파란색 — синий.", "<b>무슨 색</b> — what colour? Answer: 파란색 — blue."],
  t128: ["<b>장미</b> — роза, <b>송이</b> — счётное слово для цветов. Это <b>꽃집</b> (цветочный магазин).", "<b>장미</b> — rose, <b>송이</b> — counter for flowers. It's a <b>꽃집</b> (flower shop)."],
  t129: ["<b>이</b> — зуб. Зубная боль — <b>치과</b> (стоматология). 안경점 — оптика.", "<b>이</b> — tooth. Toothache — <b>치과</b> (dentist). 안경점 — optician."],
  t130: ["<b>몇 분이세요?</b> — сколько вас? (вежл.). Выбор столика — <b>식당</b> (ресторан). 자리 — место.", "<b>몇 분이세요?</b> — how many of you? (polite). Choosing a table — <b>식당</b> (restaurant). 자리 — seat."],
  t131: ["Ходьба, походы в горы — <b>운동</b> (физкультура). -씩 — по (каждый раз).", "Walking, hiking — <b>운동</b> (exercise). -씩 — each time."],
  t132: ["Поездка на Чеджу в отпуск, билет на самолёт — <b>여행</b> (путешествие).", "A holiday trip to Jeju and a plane ticket — <b>여행</b> (travel)."],
  t133: ["회사원 — офисный служащий, 간호사 — медсестра: <b>직업</b> (профессия).", "회사원 — office worker, 간호사 — nurse: <b>직업</b> (occupation)."],
  t134: ["Сумку подарила старшая сестра на день рождения — мужчина её <b>получил</b>. 누나 — старшая сестра (у мужчины).", "His older sister gave him the bag as a birthday gift — he <b>received</b> it. 누나 — older sister (of a male)."],
  t135: ["Женщина в выходные <b>подрабатывает</b> и в горы не идёт. 아르바이트 — подработка.", "The woman <b>works a part-time job</b> at the weekend, so she won't go hiking. 아르바이트 — part-time job."],
  t136: ["<b>N밖에 없다</b> — «есть только N». Брюки только красные. 치마 — юбка.", "<b>N밖에 없다</b> — \"there's only N\". The trousers only come in red. 치마 — skirt."],
  t137: ["Когда угощают: <b>맛있겠어요</b> — выглядит вкусно, <b>잘 먹을게요</b> — спасибо, с удовольствием.", "When offered food: <b>맛있겠어요</b> — looks delicious, <b>잘 먹을게요</b> — thanks, I'll enjoy it."],
  t138: ["<b>길이 막히다</b> — пробка. Логичное продолжение: 그럼 지하철을 탈까요? — тогда поедем на метро?", "<b>길이 막히다</b> — traffic jam. A logical reply: 그럼 지하철을 탈까요? — shall we take the subway then?"],
  t139: ["<b>주말 잘 보내세요</b> — «Хороших выходных». Отвечают тем же пожеланием.", "<b>주말 잘 보내세요</b> — \"Have a nice weekend\". Reply with the same wish."],
  t140: ["Билет в кино и место — <b>극장</b> (кинотеатр). 뒤쪽 — сзади.", "A film ticket and a seat — <b>극장</b> (cinema). 뒤쪽 — towards the back."],
  t141: ["<b>운동화</b> — кроссовки, <b>사이즈</b> — размер: покупка в обувном магазине. На реальном экзамене варианты — рисунки.", "<b>운동화</b> — sneakers, <b>사이즈</b> — size: shopping at a shoe store. In the real exam the options are drawings."],
  t142: ["<b>편지를 쓰고 있어요</b> — пишу письмо. <b>-고 있다</b> — действие в процессе. На реальном экзамене варианты — рисунки.", "<b>편지를 쓰고 있어요</b> — I'm writing a letter. <b>-고 있다</b> — an action in progress. In the real exam the options are drawings."],
  t143: ["Идёт дождь, они идут под одним зонтом: <b>우산을 같이 쓰다</b>. На реальном экзамене варианты — рисунки.", "It's raining and they share one umbrella: <b>우산을 같이 쓰다</b>. In the real exam the options are drawings."],
  t144: ["<b>다리를 다쳤어요</b> — повредила ногу. 넘어지다 — упасть. На реальном экзамене варианты — рисунки.", "<b>다리를 다쳤어요</b> — I hurt my leg. 넘어지다 — to fall. In the real exam the options are drawings."],
  t145: ["Мысль женщины: в будни нет времени, поэтому <b>в выходные нужно заниматься спортом</b>. -아/어야 — только если.", "Her point: weekdays are too busy, so <b>you should exercise at the weekend</b>. -아/어야 — only if."],
  t146: ["Женщина: нельзя покупать много только потому, что дёшево; <b>покупать только нужное</b>. 벌 — счётное слово для одежды.", "She says don't buy a lot just because it's cheap; <b>buy only what you need</b>. 벌 — counter for clothes."],
  t147: ["Совет женщины: <b>учить слова, составляя с ними предложения</b> — так дольше помнишь. 외우다 — заучивать.", "Her tip: <b>learn words by making sentences with them</b> — you'll remember longer. 외우다 — to memorise."],
  t148: ["Главная мысль женщины — в конце: <b>лучше ложиться рано</b>. 충분히 — достаточно.", "Her main idea comes at the end: <b>it's better to go to bed early</b>. 충분히 — enough."],
  t149: ["Женщина: <b>поездку лучше планировать заранее</b>. 미리 — заранее, 정하다 — решать.", "She says <b>plan trips in advance</b>. 미리 — in advance, 정하다 — to decide."],
  t237: ["Первое предложение — самостоятельное: (나). <b>그런데</b> — однако (다), <b>그래서</b> — поэтому (가), затем (라).", "The first sentence must stand alone: (나). <b>그런데</b> — however (다), <b>그래서</b> — so (가), then (라)."],
  t238: ["Приезд (가) → трудности (다) → <b>그래서</b> учёба (나) → результат (라). 덕분에 — благодаря.", "Arrival (가) → difficulty (다) → <b>그래서</b> studying (나) → result (라). 덕분에 — thanks to."],
  t239: ["Проблема (나) → <b>그래서</b> решение (라) → <b>그 후에</b> тренировка (가) → <b>지금은</b> результат (다). 지각하다 — опаздывать.", "Problem (나) → <b>그래서</b> fix (라) → <b>그 후에</b> practice (가) → <b>지금은</b> result (다). 지각하다 — to be late."],
  t240: ["Сначала открывается ресторан (나), <b>이 식당</b> — этот ресторан (가), следствие (다), план (라). 생기다 — появиться.", "First a new restaurant opens (나), <b>이 식당</b> refers back to it (가), consequence (다), plan (라). 생기다 — to appear."],
  t201: ["<b>안내 말씀 드리겠습니다</b> — объявление. Женщина <b>сообщает</b> об акции. 행사 — мероприятие, акция.", "<b>안내 말씀 드리겠습니다</b> — an announcement. She is <b>announcing</b> a sale event. 행사 — event."],
  t202: ["<b>1층 식품 매장</b> — продуктовый отдел на 1 этаже. Акция 15:00–18:00, только на фрукты.", "<b>1층 식품 매장</b> — the food section on the 1st floor. The sale runs 3–6 p.m., fruit only."],
  t203: ["Учитель <b>информирует о школьном фестивале</b>. 축제 — фестиваль, 운동장 — спортплощадка.", "She is <b>giving information about the school festival</b>. 축제 — festival, 운동장 — sports field."],
  t204: ["<b>수업이 없습니다</b> — занятий нет. Обед даёт школа, фестиваль в пятницу, прийти к 10 утра.", "<b>수업이 없습니다</b> — no classes. The school provides lunch, it's on Friday, arrive by 10 a.m."],
  t205: ["Оба говорят о том, <b>что будут делать на каникулах</b>: <b>방학 계획</b> — планы на каникулы.", "They're talking about <b>what they'll do during the break</b>: <b>방학 계획</b> — vacation plans."],
  t206: ["Мужчина будет <b>подрабатывать</b> и копить на поездку в следующие каникулы. 모으다 — копить.", "The man will <b>work part-time</b> and save for a trip next break. 모으다 — to save up."],
  t207: ["Речь о <b>квартире для переезда</b>: где её найти. 이사하다 — переезжать.", "They're discussing <b>a place to move to</b>. 이사하다 — to move house."],
  t208: ["<b>아직요</b> — ещё нет: жильё не найдено. Возле школы дорого, мужчина поедет в выходные.", "<b>아직요</b> — not yet: he hasn't found a place. Near school is expensive; he'll go at the weekend."],
  t209: ["Он стал учителем, потому что <b>радовался успехам друзей</b>. <b>그래서</b> указывает на причину.", "He became a teacher because <b>teaching his friends made him happy</b>. <b>그래서</b> signals the reason."],
  t210: ["<b>대학교 때</b> — во время учёбы в университете учил иностранных друзей. Сейчас ему тоже нравится.", "<b>대학교 때</b> — back in university he taught foreign friends. He still enjoys it now."],
  t211: ["<b>-아/어서요</b> — причина: младшая сестра <b>больше любит чёрный</b>. 바꾸다 — менять.", "<b>-아/어서요</b> gives the reason: her sibling <b>prefers black</b>. 바꾸다 — to exchange."],
  t212: ["<b>영수증도 가지고 왔어요</b> — чек тоже принесла. Часы куплены вчера, это подарок сестре.", "<b>영수증도 가지고 왔어요</b> — she brought the receipt. The watch was bought yesterday as a gift for her sibling."],
  t213: ["Выбрал интересные книги — дети слушали <b>с интересом</b>: <b>재미있게</b>. -게 образует наречие.", "Interesting books made the children listen <b>with interest</b>: <b>재미있게</b>. -게 forms an adverb."],
  t214: ["<b>매주 토요일</b> = 토요일마다 — каждую субботу. Сначала дети не сидели тихо.", "<b>매주 토요일</b> = 토요일마다 — every Saturday. At first the children weren't quiet."],
  t215: ["Угостив соседей ттоком, можно <b>дружно</b> жить с ними: <b>친하게 지내다</b>.", "Sharing rice cakes helps you <b>get along well</b> with neighbours: <b>친하게 지내다</b>."],
  t216: ["Текст об <b>обычае угощать соседей ттоком после переезда</b> и его смысле.", "The text is about <b>the custom of giving rice cakes after moving</b> and why."],
  t217: ["<b>-(으)ㄹ 수 있다</b> — «могу»: <b>말할 수 있습니다</b>. Другие формы с 수 не сочетаются.", "<b>-(으)ㄹ 수 있다</b> — \"can\": <b>말할 수 있습니다</b>. The other forms don't combine with 수."],
  t218: ["<b>퇴근 후에 매일 한 시간씩</b> — после работы по часу каждый день. Работает 1 год.", "<b>퇴근 후에 매일 한 시간씩</b> — an hour every day after work. He has worked there 1 year."],
  t219: ["Сначала плюсы, затем минус: нужен союз противопоставления <b>하지만</b> — но.", "Advantages first, then a drawback: the contrast word <b>하지만</b> — but."],
  t220: ["<b>교통비가 들지 않다</b> — не тратишься на проезд. Велосипедистов стало больше.", "<b>교통비가 들지 않다</b> — no transport costs. More people now cycle to work."],
  t221: ["«Думал, что бы принести» → <b>그래서</b> приготовил плов. Значит, место — ㉠. 고민하다 — раздумывать.", "\"I wondered what to bring\" → <b>그래서</b> I made plov. So it goes in ㉠. 고민하다 — to agonise over."],
  t222: ["<b>처음으로 초대를 받았습니다</b> — меня впервые пригласили. Плов сделал я, 불고기 — мама друга.", "<b>처음으로 초대를 받았습니다</b> — invited for the first time. I made plov; the friend's mother made 불고기."],
  t223: ["Дёшево и вкусно, поэтому сотрудники часто <b>пользуются</b> кафе: <b>이용하다</b>.", "Cheap and tasty, so staff often <b>use</b> it: <b>이용하다</b>."],
  t224: ["<b>1층</b> — первый этаж. В кафе подрабатывают студенты, я хожу после обеда.", "<b>1층</b> — the first floor. Students work there; I go after lunch."],
  t225: ["Тема: <b>수업 장소 변경 안내</b> — смена места занятий. Цель — сообщить.", "Subject: <b>수업 장소 변경 안내</b> — change of class location. The purpose is to inform."],
  t226: ["Сейчас 2 этаж, <b>со следующей недели — 3 этаж, кабинет 305</b>. Время прежнее.", "Now on the 2nd floor; <b>from next week, room 305 on the 3rd</b>. The time stays the same."],
  t227: ["Для кимчи есть особый глагол: <b>김치를 담그다</b> (заквашивать, готовить).", "Kimchi has its own verb: <b>김치를 담그다</b> (to make, pickle)."],
  t228: ["<b>가을에 김치를 많이 만들어 두었습니다</b> — осенью готовили много кимчи впрок: это <b>김장</b>.", "<b>가을에 김치를 많이 만들어 두었습니다</b> — lots of kimchi was made in autumn: that's <b>김장</b>."],
  t229: ["Громко говорить плохо, значит говорить нужно <b>медленно, спокойно</b>: <b>천천히</b>.", "Speaking loudly is bad, so speak <b>slowly and calmly</b>: <b>천천히</b>."],
  t230: ["<b>문제가 더 커질 수 있습니다</b> — проблема может вырасти. 화가 나다 — злиться, 숨을 쉬다 — дышать.", "<b>문제가 더 커질 수 있습니다</b> — the problem can get bigger. 화가 나다 — to get angry, 숨을 쉬다 — to breathe."],
  t231: ["«Не было времени снимать то, что <b>хотелось снимать</b>»: <b>-고 싶은</b> + сущ.", "\"No time to take the photos <b>I wanted to take</b>\": <b>-고 싶은</b> + noun."],
  t232: ["<b>작은 사진관을 열었습니다</b> — открыл маленькую фотостудию и сейчас работает там.", "<b>작은 사진관을 열었습니다</b> — he opened a small photo studio and works there now."],
  t233: ["Трудно, <b>но</b> интересно: <b>-지만</b>. -아서 — причина, -면 — условие, -거나 — или.", "Hard <b>but</b> fun: <b>-지만</b>. -아서 — reason, -면 — condition, -거나 — or."],
  t234: ["<b>쉬는 시간</b> — перемена: ученики учат друг друга своим языкам.", "<b>쉬는 시간</b> — break time: classmates teach each other their languages."],
  t235: ["После плюса — проблема: <b>그런데</b> (однако). 그래서/그러니까 — поэтому.", "A drawback after a benefit: <b>그런데</b> (however). 그래서/그러니까 — so."],
  t236: ["<b>커피 대신 차</b> — чай вместо кофе после 15:00. 대신 — вместо.", "<b>커피 대신 차</b> — tea instead of coffee after 3 p.m. 대신 — instead of."],
  t241: ["После месяца тренировок даже 30 минут бегает <b>легко</b>: <b>쉽게</b>. Сначала было трудно и 10 минут.", "After a month of training he runs 30 minutes <b>easily</b>: <b>쉽게</b>. At first even 10 minutes was hard."],
  t242: ["<b>아침마다</b> — каждое утро. Благодаря спорту хорошо спит.", "<b>아침마다</b> — every morning. Thanks to exercise he sleeps well."],
  t243: ["Последовательность: <b>-고</b> — «и, держа». Не едят, <b>держа</b> чашку в руке: 들고 먹지 않습니다.", "Linked actions: <b>-고</b>. Koreans don't eat <b>holding</b> the rice bowl: 들고 먹지 않습니다."],
  t244: ["Ложка, палочки, чашка на столе — это <b>식사 예절</b> (застольный этикет).", "Spoons, chopsticks, keeping the bowl on the table — <b>식사 예절</b> (table manners)."],
  t245: ["Гуляя по цветущей аллее, <b>настроение</b> улучшается: <b>기분이 좋아지다</b>.", "Walking among the blossoms, your <b>mood</b> improves: <b>기분이 좋아지다</b>."],
  t246: ["Текст о <b>весенних фестивалях цветов</b>. 벚꽃 — сакура, 열리다 — проводиться.", "The text is about <b>spring flower festivals</b>. 벚꽃 — cherry blossoms, 열리다 — to be held."],
  t247: ["Проверяет вещи <b>перед</b> выходом из автобуса: <b>-기 전에</b>.", "He checks his things <b>before</b> getting off: <b>-기 전에</b>."],
  t248: ["Телефон остался на сиденье <b>в автобусе</b> и не нашёлся, купил новый. 잃어버리다 — потерять.", "The phone was left on a <b>bus</b> seat and never found; he bought a new one. 잃어버리다 — to lose."],
  t249: ["Книгами делятся — <b>денег не нужно</b>: <b>돈이 들지 않다</b>. 돈이 들다 — требовать затрат.", "Books are shared — <b>it costs nothing</b>: <b>돈이 들지 않다</b>. 돈이 들다 — to cost money."],
  t250: ["<b>주민</b> — жильцы: приносят прочитанные книги и делятся. Я взял кулинарные книги.", "<b>주민</b> — residents bring books they've read and share them. I borrowed cookbooks."],
  t251: ["Полезное блюдо, <b>однако</b> в день экзамена его не едят — противопоставление: <b>그런데</b>.", "A healthy dish, <b>but</b> not eaten on exam day — contrast: <b>그런데</b>."],
  t252: ["<b>미역국</b> — суп из морской капусты, его едят в день рождения. 떨어지다 — упасть; провалить экзамен.", "<b>미역국</b> — seaweed soup, eaten on birthdays. 떨어지다 — to fall; to fail an exam."],
  t253: ["<b>하지만</b> противопоставляется трудностям: после травм рук и перед «сейчас 10 блюд» — ㉡.", "<b>하지만</b> contrasts with the earlier struggle: after the cut hands, before \"now 10 dishes\" — ㉡."],
  t254: ["<b>주말마다 요리 학원에 다닙니다</b> — каждые выходные хожу на кулинарные курсы.", "<b>주말마다 요리 학원에 다닙니다</b> — I attend cooking classes every weekend."],
  t255: ["Дождь — причина смены плана: между «собирались пойти» и «<b>그래서</b> вместо гор — ресторан» — ㉡.", "The rain explains the change: between \"we planned to go\" and \"<b>그래서</b> a restaurant instead\" — ㉡."],
  t256: ["Из-за дождя в горы <b>не пошли</b>, пообедали в ресторане. 부서 — отдел.", "Because of rain they <b>couldn't go</b> to the mountain and had lunch out. 부서 — department."],
  t257: ["Дёшево и можно поесть <b>просто, быстро</b>: <b>간단하게</b>. Поэтому популярно.", "Cheap and <b>quick and easy</b> to eat: <b>간단하게</b>. That's why it's popular."],
  t258: ["<b>값이 싸다</b> — дёшево. Одиноких стало больше; питаться только так — вредно.", "<b>값이 싸다</b> — cheap. More people live alone; eating only this is unhealthy."],
  t259: ["<b>Играя</b> в футбол, улучшил и корейский: <b>-(으)면서</b> — одновременно.", "<b>While</b> playing football, his Korean improved too: <b>-(으)면서</b>."],
  t260: ["Вступил в <b>동아리</b> (клуб), чтобы подружиться с корейцами. 2 раза в неделю, после игры едят вместе.", "He joined a <b>동아리</b> (club) to make Korean friends. Twice a week; they eat together after games."],
  t261: ["Тема <b>생일 파티 초대</b> — приглашение на день рождения. Цель письма — пригласить.", "Subject <b>생일 파티 초대</b> — a birthday party invitation. The purpose is to invite."],
  t262: ["Праздник <b>в субботу в 19:00</b> дома у Надиры. Ответить нужно до пятницы.", "The party is <b>Saturday at 7 p.m.</b> at Nadira's home. Reply by Friday."],
  t263: ["<b>점검 안내</b> — уведомление о техосмотре. 관리사무소 — управляющая компания.", "<b>점검 안내</b> — a maintenance notice. 관리사무소 — building management office."],
  t264: ["В четверг <b>с 9 до 12</b> лифт не работает, просят пользоваться лестницей. 계단 — лестница.", "On Thursday <b>9–12 a.m.</b> the elevator is out; use the stairs. 계단 — stairs."],
  t265: ["Даже если место свободно, молодые туда <b>не садятся</b>: <b>잘 앉지 않습니다</b>.", "Even when it's empty, young people <b>don't sit</b> there: <b>잘 앉지 않습니다</b>."],
  t266: ["<b>노약자석</b> — места для пожилых, беременных и людей с ограничениями. 불편하다 — неудобно.", "<b>노약자석</b> — seats for the elderly, pregnant and disabled. 불편하다 — uncomfortable."],
  t267: ["Когда хочется пить, воды в теле уже <b>не хватает</b>: <b>부족하다</b>.", "By the time you're thirsty, your body is already <b>short</b> of water: <b>부족하다</b>."],
  t268: ["Вывод: пейте понемногу и часто, <b>даже если не хочется</b>. 조금씩 — понемногу.", "Conclusion: drink little and often <b>even when not thirsty</b>. 조금씩 — a little at a time."],
  t269: ["Сухой воздух нужно увлажнять: <b>가습기</b> (увлажнитель) или мокрое полотенце. -거나 — или.", "Dry air needs moisture: a <b>가습기</b> (humidifier) or a wet towel. -거나 — or."],
  t270: ["Чтобы не простыть, нужно <b>часто мыть руки</b>. 건조하다 — сухой, 유지하다 — поддерживать.", "To avoid colds, <b>wash your hands often</b>. 건조하다 — dry, 유지하다 — to maintain."],
  t271: ["Поощрение за свою кружку — <b>скидка</b> на напиток: <b>할인해 주다</b>.", "The reward for bringing your own cup is a <b>discount</b>: <b>할인해 주다</b>."],
  t272: ["Одноразовые стаканы дают много мусора, своя кружка его <b>уменьшает</b>. 환경 — окружающая среда.", "Disposable cups create waste; a personal cup <b>reduces</b> it. 환경 — the environment."],
  t273: ["Пациентам стало спокойнее — живопись может <b>утешать</b> людей: <b>위로하다</b>.", "The patients felt at ease — art can <b>comfort</b> people: <b>위로하다</b>."],
  t274: ["Он стал <b>врачом</b>, но в свободное время продолжает рисовать. 의학 — медицина, 전시회 — выставка.", "He became a <b>doctor</b> but still paints in his free time. 의학 — medicine, 전시회 — exhibition."],
  t275: ["Даже без покупки <b>угощает</b> чаем: <b>차를 대접하다</b>. -시- — суффикс вежливости.", "Even without a purchase she <b>treats</b> them to tea: <b>차를 대접하다</b>. -시- — honorific suffix."],
  t276: ["В лавку <b>часто приходят соседи поговорить</b>. 시골 — деревня, 마을 — село.", "<b>Villagers often gather</b> at the shop to chat. 시골 — countryside, 마을 — village."],
  t277: ["Объявление в метро: <b>сообщает станцию и выход</b>. 승객 — пассажир, 내리다 — выходить.", "A subway announcement: <b>it gives the station and exit side</b>. 승객 — passenger, 내리다 — to get off."],
  t278: ["<b>내리실 문은 오른쪽입니다</b> — выход справа. Для поезда в Пусан выходят здесь, на Сеульском вокзале.", "<b>내리실 문은 오른쪽입니다</b> — doors open on the right. For Busan trains, get off here at Seoul Station."],
  t279: ["Весь разговор о том, как женщина <b>учится плавать</b>.", "The whole conversation is about her <b>learning to swim</b>."],
  t280: ["<b>일주일에 세 번</b> — три раза в неделю. Сначала было страшно, теперь интересно. 무섭다 — страшный.", "<b>일주일에 세 번</b> — three times a week. It was scary at first, now it's fun. 무섭다 — scary."],
  t281: ["<b>-거든요</b> объясняет причину: он <b>переехал поближе к работе</b>.", "<b>-거든요</b> explains the reason: he <b>moved near the office</b>."],
  t282: ["<b>걸어서 10분</b> — 10 минут пешком. Раньше с двумя пересадками ехал больше часа.", "<b>걸어서 10분</b> — 10 minutes on foot. Before, two bus changes took over an hour."],
  t335: ["Первое предложение — самостоятельное (без союза). Дальше цепочка союзов: проблема (나) → <b>그래서</b> (가) → <b>이제</b> (다) → (라). 살이 찌다 — поправиться.", "The first sentence stands alone (no connector). Then follow the connectors: problem (나) → <b>그래서</b> (가) → <b>이제</b> (다) → (라). 살이 찌다 — to gain weight."],
  t336: ["Первое предложение — самостоятельное (без союза). Дальше цепочка союзов: знакомство с другом (나) → <b>그 친구</b> (가) → <b>그래서</b> (라) → план (다).", "The first sentence stands alone (no connector). Then follow the connectors: introducing the friend (나) → <b>그 친구</b> (가) → <b>그래서</b> (라) → plan (다)."],
  t337: ["Первое предложение — самостоятельное (без союза). Дальше цепочка союзов: план (나) → <b>그런데</b> (가) → <b>그래서</b> (라) → итог (다). -기로 하다 — договориться.", "The first sentence stands alone (no connector). Then follow the connectors: plan (나) → <b>그런데</b> (가) → <b>그래서</b> (라) → outcome (다). -기로 하다 — to agree to."],
  t338: ["Первое предложение — самостоятельное (без союза). Дальше цепочка союзов: ферма (나) → много работы (라) → <b>그래서</b> помогаю (가) → после работы (다). 따다 — собирать.", "The first sentence stands alone (no connector). Then follow the connectors: the farm (나) → lots of work (라) → <b>그래서</b> I help (가) → after work (다). 따다 — to pick."],
  t339: ["<b>두통약</b> — лекарство от головной боли: аптека. На реальном экзамене варианты — рисунки.", "<b>두통약</b> — headache medicine: a pharmacy. In the real exam the options are drawings."],
  t340: ["<b>사진을 찍어 주다</b> — сфотографировать кого-то. На реальном экзамене варианты — рисунки.", "<b>사진을 찍어 주다</b> — to take a photo for someone. In the real exam the options are drawings."],
  t341: ["Холодно, просят <b>закрыть окно</b>: 창문을 닫다. На реальном экзамене варианты — рисунки.", "It's cold; she asks him to <b>close the window</b>: 창문을 닫다. In the real exam the options are drawings."],
  t342: ["Молоко кладут <b>в холодильник</b>: 냉장고에 넣다. На реальном экзамене варианты — рисунки.", "The milk goes <b>in the fridge</b>: 냉장고에 넣다. In the real exam the options are drawings."],
  t343: ["Мысль женщины — в <b>-아/어야 해요</b>: перед выездом <b>обязательно проверить погоду</b>.", "Her point is in <b>-아/어야 해요</b>: <b>check the weather</b> before you leave."],
  t344: ["<b>-(으)ㄹ수록</b> — чем больше…, тем…: даже при большой нагрузке <b>нужно ненадолго отдыхать</b>.", "<b>-(으)ㄹ수록</b> — the more…: the busier you are, <b>the more you need short breaks</b>."],
  t345: ["<b>중고</b> — б/у. Мысль женщины: <b>и подержанная вещь хороша, если выбрать с умом</b>.", "<b>중고</b> — second-hand. Her point: <b>a used item is fine if you choose carefully</b>."],
  t346: ["Женщина: <b>свяжитесь первым</b>, со временем извиниться труднее. 싸우다 — ссориться.", "She says <b>reach out first</b>; the longer you wait, the harder it is to apologise. 싸우다 — to quarrel."],
  t283: ["Продавщица каждый раз <b>даёт</b> лишний фрукт: <b>주다</b> → 주십니다 (вежл.).", "The lady <b>gives</b> an extra fruit each time: <b>주다</b> → 주십니다 (honorific)."],
  t284: ["<b>마트보다 값이 싸다</b> — дешевле, чем в супермаркете. 친절하다 — приветливый.", "<b>마트보다 값이 싸다</b> — cheaper than the supermarket. 친절하다 — kind."],
  t285: ["<b>줄을 서다</b> — стоять в очереди. Пекарне 30 лет, она очень популярна.", "<b>줄을 서다</b> — to stand in line. The 30-year-old bakery is very popular."],
  t286: ["<b>30년 동안</b> — 30 лет на одном месте. Открывается в 7 утра, я покупаю по выходным.", "<b>30년 동안</b> — for 30 years in one spot. It opens at 7 a.m.; I buy there at weekends."],
  t287: ["<b>-다고 말하다</b> — «говорят, что…» (косвенная речь). Съел ттоккук — стал на год старше.", "<b>-다고 말하다</b> — \"people say that…\" (reported speech). Eating 떡국 makes you a year older."],
  t288: ["Ттоккук, 세배 (поклон), 세뱃돈 — <b>обычаи Нового года (설날)</b>.", "떡국, 세배 (a deep bow), 세뱃돈 — <b>Lunar New Year (설날) customs</b>."],
  t289: ["Всё в телефоне — жизнь <b>стала удобнее</b>: <b>편리하다</b> + -아/어지다 (изменение).", "Everything's on the phone — life <b>became convenient</b>: <b>편리하다</b> + -아/어지다 (change)."],
  t290: ["Текст о том, <b>что можно делать с телефоном</b>.", "The text is about <b>what you can do with a phone</b>."],
  t291: ["Цель: <b>-(으)려고</b> — «чтобы». Старается, чтобы окончить в следующем году.", "Purpose: <b>-(으)려고</b> — \"in order to\". Working hard to graduate next year."],
  t292: ["Днём работает, <b>вечером</b> учится в магистратуре. 대학원 — магистратура.", "Works by day and studies <b>in the evening</b> at grad school. 대학원 — graduate school."],
  t293: ["Если что-то не знали, <b>спрашивали</b> у Аны: <b>물어보다</b>.", "When unsure, they would <b>ask</b> Ana: <b>물어보다</b>."],
  t294: ["Ана <b>лучше всех</b> в классе знала корейский. Ей подарили альбом.", "Ana spoke Korean <b>best</b> in the class. They gave her a photo album."],
  t295: ["Было трудно, <b>но</b> коллеги помогли — противопоставление: <b>하지만</b>.", "It was hard, <b>but</b> coworkers helped — contrast: <b>하지만</b>."],
  t296: ["<b>도와주었습니다</b> — помогли. 취직하다 — устроиться на работу, 적응하다 — адаптироваться.", "<b>도와주었습니다</b> — they helped. 취직하다 — to get a job, 적응하다 — to adapt."],
  t297: ["Сначала было медленно, <b>однако</b> теперь быстро — <b>그런데</b>.", "Slow at first, <b>but</b> now fast — <b>그런데</b> (contrast)."],
  t298: ["<b>매일 일기를 한국어로</b> — каждый день дневник по-корейски. Теперь пишет за 10 минут.", "<b>매일 일기를 한국어로</b> — a daily diary in Korean. Now it takes 10 minutes."],
  t299: ["<b>그래서</b> — следствие помощи людей; после этого «хочу снова» — ㉢.", "<b>그래서</b> follows from people helping; then \"I want to go again\" — ㉢."],
  t300: ["<b>처음으로 혼자</b> — впервые путешествовал один. 여행지 — место поездки.", "<b>처음으로 혼자</b> — travelled alone for the first time. 여행지 — destination."],
  t301: ["Предложение — результат моих прогулок: после «я тоже гуляю», в конце — ㉣.", "This is the result of my walking, so it comes after \"I walk too\", at the end — ㉣."],
  t302: ["<b>운동 기구</b> — тренажёры. Парк новый, я гуляю после работы (вечером).", "<b>운동 기구</b> — exercise equipment. The park is new; I walk after work (evenings)."],
  t303: ["<b>시간과 돈이 들다</b> — требует времени и денег. 들다 — уходить, тратиться.", "<b>시간과 돈이 들다</b> — it takes time and money. 들다 — to be needed, to cost."],
  t304: ["<b>외로움을 줄여 주다</b> — уменьшает одиночество. 반려동물 — домашний питомец.", "<b>외로움을 줄여 주다</b> — eases loneliness. 반려동물 — pet."],
  t305: ["<b>거의</b> — почти (в утверждении). 전혀/별로 — только с отрицанием, 아직 — ещё.", "<b>거의</b> — almost (with a positive). 전혀/별로 need a negative; 아직 — yet."],
  t306: ["Учит язык по дорамам. Сначала с корейскими субтитрами, теперь без. 자막 — субтитры.", "He learns from dramas: first with Korean subtitles, now without. 자막 — subtitles."],
  t307: ["<b>결석</b> — пропуск занятия. Цель письма — <b>сообщить, что не придёт</b>.", "<b>결석</b> — absence. The purpose is <b>to say he can't come today</b>."],
  t308: ["Температура и боль в горле — <b>сегодня идёт в больницу</b>. Домашку спросит у друга.", "Fever and sore throat — <b>he's going to hospital today</b>. He'll ask a friend for the homework."],
  t309: ["Тема <b>할인 행사 안내</b> — объявление о скидочной акции.", "Subject <b>할인 행사 안내</b> — a notice about a discount event."],
  t310: ["<b>계산대에서 바로 만들 수 있습니다</b> — карту оформят прямо на кассе. Скидка только на фрукты и овощи, 7 дней.", "<b>계산대에서 바로 만들 수 있습니다</b> — you can get a card at the checkout. Only fruit and veg, for 7 days."],
  t311: ["<b>-게 하다</b> — побудительная форма: дают малышу <b>взять</b> один предмет. 잡다 — хватать.", "<b>-게 하다</b> — causative: they let the baby <b>grab</b> one item. 잡다 — to grab."],
  t312: ["<b>돌잔치</b> — праздник первого дня рождения малыша. Карандаш — учёба, деньги — богатство.", "<b>돌잔치</b> — a baby's first-birthday party. Pencil = good student, money = wealth."],
  t313: ["Если ложиться в одно время, тело <b>привыкает</b>: <b>익숙해지다</b>.", "Sleeping at the same time daily, the body <b>gets used to it</b>: <b>익숙해지다</b>."],
  t314: ["Яркий свет телефона мешает уснуть — <b>не смотрите в него перед сном</b>.", "The phone's bright light keeps you awake — <b>don't look at it before bed</b>."],
  t315: ["Сравнение с <b>보다</b>: всё больше людей <b>предпочитают</b> обед или концерт застолью.", "With <b>보다</b>: more people now <b>prefer</b> lunch or a show to drinking dinners."],
  t316: ["<b>회식</b> — совместный ужин коллег после работы; помогает сблизиться.", "<b>회식</b> — a meal with coworkers after work; it helps people bond."],
  t317: ["Большой пакет дороже — значит, кто <b>выбрасывает много</b>, платит больше.", "Bigger bags cost more, so those who <b>throw away a lot</b> pay more."],
  t318: ["<b>종량제 봉투</b> — платный мусорный пакет; продаётся в магазинах. 제도 — система.", "<b>종량제 봉투</b> — a paid rubbish bag sold at stores. 제도 — system."],
  t319: ["Сам сначала <b>испытал трудности</b>, поэтому рад помогать: <b>-기 때문에</b>.", "Because <b>it was hard</b> for him at first, he's glad to help: <b>-기 때문에</b>."],
  t320: ["Сейчас <b>помогает узбекам, приехавшим в Корею</b>. 통역 — устный перевод.", "Now he <b>helps Uzbeks who come to Korea</b>. 통역 — interpreting."],
  t321: ["Будет ветеринаром — клиника, <b>где лечат больных животных</b>: <b>돌보다</b> — ухаживать.", "A future vet — a clinic that <b>cares for sick animals</b>: <b>돌보다</b> — to look after."],
  t322: ["В этом году поступил на <b>ветеринарный факультет</b> — сейчас учится. 수의사 — ветеринар.", "This year he entered <b>veterinary school</b>, so he's studying now. 수의사 — vet."],
  t323: ["<b>알려 드립니다</b> — сообщаем: о графике уборки бассейна.", "<b>알려 드립니다</b> — we inform you: about the pool cleaning schedule."],
  t324: ["С понедельника по среду закрыто, <b>с четверга</b> снова открыто.", "Closed Monday to Wednesday, open again <b>from Thursday</b>."],
  t325: ["<b>견학</b> — экскурсия. Учитель <b>объясняет программу экскурсии</b>.", "<b>견학</b> — a field trip. She is <b>explaining the trip schedule</b>."],
  t326: ["<b>사진을 찍을 수 없습니다</b> — фотографировать нельзя. Автобус отходит от школы в 9.", "<b>사진을 찍을 수 없습니다</b> — no photos. The bus leaves from school at 9."],
  t327: ["Они обсуждают, <b>что подарить на свадьбу</b>.", "They discuss <b>what to give as a wedding gift</b>."],
  t328: ["Мужчина в выходные идёт <b>на свадьбу друга</b> и подарит посуду. 신혼부부 — молодожёны.", "He's going to <b>a friend's wedding</b> and will give dishes. 신혼부부 — newlyweds."],
  t329: ["Речь о том, <b>как заниматься по книге</b>: читать вместе с аудио.", "They talk about <b>how to study with the book</b>: read along with the audio."],
  t330: ["<b>생각보다 어려워요</b> — труднее, чем думала. Аудио попробует сегодня.", "<b>생각보다 어려워요</b> — harder than she thought. She'll try the audio today."],
  t331: ["<b>-거든요</b> объясняет причину: готовит только <b>из купленного в тот же день</b>.", "<b>-거든요</b> gives the reason: he cooks only <b>with that day's ingredients</b>."],
  t332: ["<b>아침마다 시장에</b> — каждое утро на рынок. 재료가 떨어지다 — продукты кончаются.", "<b>아침마다 시장에</b> — to the market every morning. 재료가 떨어지다 — to run out of ingredients."],
  t333: ["<b>-고 싶어서요</b> — причина: хочет глубже изучать дизайн. 유학 — учёба за границей.", "<b>-고 싶어서요</b> — the reason: she wants to study design more. 유학 — studying abroad."],
  t334: ["В следующем месяце едет <b>учиться в Италию</b> на 2 года. -다면서요? — «говорят, что…?»", "Next month she goes <b>to study in Italy</b> for 2 years. -다면서요? — \"I heard that…?\""]
};
